const CONTAINERS = [
  { key: "cans330", label: "330ml Can", shortLabel: "Can", volumeL: 0.33 },
  { key: "kegs20", label: "20L Keg", shortLabel: "20L Keg", volumeL: 20 },
  { key: "kegs30", label: "30L Keg", shortLabel: "30L Keg", volumeL: 30 },
  { key: "kegs50", label: "50L Keg", shortLabel: "50L Keg", volumeL: 50 },
];

// The key a specific product (a beer in a specific container) is
// identified by for Xero item mapping — shared globally so the mapping
// modal (outside the main app component) computes the exact same key a
// real packaged batch will use when it's actually sold.
const CANS_PER_CASE = 24;
const productKeyFor = (name, containerKey) => `${name.trim().toLowerCase()}::${containerKey}`;

// The actual point of a triangle test — a raw "8/12 correct" tells a
// brewer nothing on its own, since even random guessing gets roughly a
// third right by chance. This computes the real, one-tailed binomial
// significance (exact, not approximated) at the standard 5% threshold,
// matching how the method is actually used in sensory science — see
// ISO 4120 / ASTM E1885.
function binomialCoeff(n, k) {
  if (k < 0 || k > n) return 0;
  let result = 1;
  for (let i = 0; i < k; i++) result = (result * (n - i)) / (i + 1);
  return result;
}
function triangleTestSignificance(correct, total) {
  if (total === 0) return { pValue: 1, significant: false };
  const p = 1 / 3;
  let pValue = 0;
  for (let i = correct; i <= total; i++) {
    pValue += binomialCoeff(total, i) * Math.pow(p, i) * Math.pow(1 - p, total - i);
  }
  return { pValue, significant: pValue <= 0.05 };
}

const packagedVolume = (packaging) =>
  !packaging ? 0 : CONTAINERS.reduce((sum, c) => sum + (packaging[c.key] || 0) * c.volumeL, 0);

// Packaging is stored as { events: [{id,date,cans330,kegs20,...}], discarded: number }.
// Batches packaged before this feature existed have the old shape (container
// counts directly on the packaging object) — read those as a single legacy event.
function packagingEvents(batch) {
  if (!batch.packaging) return [];
  if (Array.isArray(batch.packaging.events)) return batch.packaging.events;
  const hasLegacyCounts = CONTAINERS.some((c) => batch.packaging[c.key] != null);
  if (hasLegacyCounts) {
    const legacy = { id: "legacy", date: batch.startDate };
    CONTAINERS.forEach((c) => (legacy[c.key] = batch.packaging[c.key] || 0));
    return [legacy];
  }
  return [];
}

const packagingDiscarded = (batch) => (batch.packaging && batch.packaging.discarded) || 0;

// Sums every packaging event on a batch into one {cans330: N, kegs20: N, ...}
// total — how much of each container size this batch has ever produced.
function packagedTotalsByContainer(batch) {
  const totals = {};
  CONTAINERS.forEach((c) => (totals[c.key] = 0));
  packagingEvents(batch).forEach((e) => {
    CONTAINERS.forEach((c) => {
      totals[c.key] += e[c.key] || 0;
    });
  });
  return totals;
}

// Same cost-per-container math already shown on a batch's own packaging
// section — spreads the batch's total ingredient cost across every litre
// actually packaged, then prices a specific container by its volume
// share. Pulled out here so sales analytics can use the identical, real
// cost basis rather than a separate approximation.
function batchCostPerContainer(batch, containerKey) {
  if (!batch.ingredientCost || batch.ingredientCost <= 0) return null;
  const totals = packagedTotalsByContainer(batch);
  const totalVolumePackaged = CONTAINERS.reduce((sum, c) => sum + (totals[c.key] || 0) * c.volumeL, 0);
  if (totalVolumePackaged <= 0) return null;
  const costPerLitre = batch.ingredientCost / totalVolumePackaged;
  const container = CONTAINERS.find((c) => c.key === containerKey);
  if (!container) return null;
  return costPerLitre * container.volumeL;
}

// Sums how much of a batch's stock is already spoken for by sales orders —
// Draft and Cancelled orders don't reserve anything, everything else does.
function soldTotalsByContainer(batchId, salesOrders) {
  const totals = {};
  CONTAINERS.forEach((c) => (totals[c.key] = 0));
  (salesOrders || []).forEach((so) => {
    if (so.status === "Draft" || so.status === "Cancelled") return;
    (so.lines || []).forEach((line) => {
      if (line.batchId === batchId && totals[line.containerKey] != null) {
        totals[line.containerKey] += Number(line.qty) || 0;
      }
    });
  });
  return totals;
}

// Every batch+container combination that's ever had stock packaged into it,
// with how much is actually still available to sell right now. This is
// what a sales order line picker is built from.
// How much of a specific batch+container has already gone into an
// assembled mixed pack — same idea as soldTotalsByContainer, just a
// different way stock leaves the "available to sell on its own" pool.
function mixedPackConsumptionByContainer(batchId, mixedPackAssemblies) {
  const totals = {};
  (mixedPackAssemblies || []).forEach((a) => {
    (a.composition || []).forEach((line) => {
      if (line.batchId !== batchId) return;
      totals[line.containerKey] = (totals[line.containerKey] || 0) + line.qtyPerPack * a.quantity;
    });
  });
  return totals;
}

function availableStockList(batches, salesOrders, mixedPackAssemblies) {
  const list = [];
  batches.forEach((b) => {
    if (!b.packaging) return;
    const packaged = packagedTotalsByContainer(b);
    const sold = soldTotalsByContainer(b.id, salesOrders);
    const consumedByMixedPacks = mixedPackConsumptionByContainer(b.id, mixedPackAssemblies);
    // Stock written off with "Clear stock" — kept off the packaging itself
    // so the excise records behind it never change.
    const cleared = {};
    (b.stockCleared || []).forEach((e) => Object.entries(e.counts || {}).forEach(([k, v]) => (cleared[k] = (cleared[k] || 0) + v)));
    // Sold on invoices raised straight in Xero (see planXeroSales).
    (b.xeroSold || []).forEach((e) => (cleared[e.containerKey] = (cleared[e.containerKey] || 0) + (Number(e.qty) || 0)));
    CONTAINERS.forEach((c) => {
      if ((packaged[c.key] || 0) > 0) {
        list.push({
          batchId: b.id,
          batchName: b.name,
          batchNumber: b.number,
          containerKey: c.key,
          containerLabel: c.label,
          packaged: packaged[c.key],
          available: (packaged[c.key] || 0) - (sold[c.key] || 0) - (consumedByMixedPacks[c.key] || 0) - (cleared[c.key] || 0),
        });
      }
    });
  });
  return list;
}

// ─── Two-way stock with Xero: sales invoiced in Xero take stock off ─────────
// Works out what a batch of Xero invoices/credit notes means for Brewpoint's
// stock, without touching anything — the caller saves the result. Every
// Xero line is recorded once (by its line id) so nothing is counted twice,
// and a voided invoice gives its stock back.
//
//  - Invoices for Brewpoint's own orders (reference = a Brewpoint order
//    number) are skipped — those orders already took the stock off.
//  - Each Xero item is matched to a beer + container, with how many
//    Brewpoint units one Xero unit holds (a case of 24 = 24 cans).
//  - Stock comes off the oldest batch first; a credit note puts it back on
//    the newest batch of that beer.
function planXeroSales({ docs, ledger, salesMap, itemMappings, batches, available, brewpointOrderNumbers }) {
  const ledgerByLine = {};
  (ledger || []).forEach((r) => (ledgerByLine[r.xero_line_id] = r));
  const orderNos = new Set((brewpointOrderNumbers || []).map((n) => String(n).trim().toLowerCase()).filter(Boolean));
  const mapByCode = {};
  (salesMap || []).forEach((m) => (mapByCode[String(m.xero_item_code).toLowerCase()] = m));

  const resolve = (code) => {
    const m = mapByCode[String(code).toLowerCase()];
    if (m) {
      if (m.ignore) return { ignore: true };
      if (m.product_key) return { productKey: m.product_key, containerKey: m.container_key || m.product_key.split("::")[1], units: Number(m.units_per_xero_unit) || 1 };
    }
    const fm = (itemMappings || []).find((x) => String(x.xero_item_code).toLowerCase() === String(code).toLowerCase());
    if (fm) return { productKey: fm.product_key, containerKey: fm.product_key.split("::")[1], units: 1 };
    return null;
  };

  const packedOn = {};
  batches.forEach((b) => (packedOn[b.id] = packagingEvents(b).reduce((mx, e) => (e.date && e.date > mx ? e.date : mx), "")));
  const avail = {};
  (available || []).forEach((s) => (avail[`${s.batchId}::${s.containerKey}`] = s.available));
  const batchesFor = (productKey, containerKey) =>
    batches.filter((b) => productKeyFor(b.name, containerKey) === productKey && packagingEvents(b).length > 0);

  const soldChanges = {}; // batchId -> new xeroSold array
  const soldOf = (b) => soldChanges[b.id] || (soldChanges[b.id] = [...(b.xeroSold || [])]);
  const batchById = Object.fromEntries(batches.map((b) => [b.id, b]));
  const rows = [];
  const unmatched = {};
  const summary = { applied: 0, units: 0, returned: 0, reversed: 0, short: 0, skipped: 0, unmapped: 0 };

  const sorted = [...(docs || [])].sort((a, b) => String(a.date).localeCompare(String(b.date)));
  sorted.forEach((doc) => {
    const active = doc.status === "AUTHORISED" || doc.status === "PAID";
    const ownOrder = doc.docType === "invoice" && doc.reference && orderNos.has(String(doc.reference).trim().toLowerCase());
    doc.lines.forEach((line) => {
      const prev = ledgerByLine[line.lineId];
      const base = {
        xero_line_id: line.lineId,
        xero_doc_id: doc.docId,
        doc_type: doc.docType,
        doc_number: doc.number,
        doc_date: doc.date,
        contact_name: doc.contactName,
        item_code: line.itemCode,
        xero_qty: line.qty,
      };

      if (!active) {
        // Voided or deleted in Xero: give back whatever it took.
        if (prev && (prev.status === "applied" || prev.status === "short")) {
          (prev.allocations || []).forEach((a) => {
            const b = batchById[a.batchId];
            if (!b) return;
            soldChanges[b.id] = soldOf(b).filter((x) => x.lineId !== line.lineId);
            avail[`${a.batchId}::${a.containerKey}`] = (avail[`${a.batchId}::${a.containerKey}`] || 0) + a.qty;
          });
          rows.push({ ...prev, ...base, status: "reversed", allocations: [] });
          summary.reversed += 1;
        }
        return;
      }
      if (prev && prev.status !== "unmapped") return; // already dealt with

      if (ownOrder) {
        rows.push({ ...base, units: 0, status: "skipped", allocations: [] });
        summary.skipped += 1;
        return;
      }
      const map = resolve(line.itemCode);
      if (!map || map.ignore) {
        if (map && map.ignore) {
          rows.push({ ...base, units: 0, status: "skipped", allocations: [] });
          summary.skipped += 1;
        } else {
          rows.push({ ...base, units: 0, status: "unmapped", allocations: [] });
          unmatched[line.itemCode] = (unmatched[line.itemCode] || 0) + 1;
          summary.unmapped += 1;
        }
        return;
      }

      const units = Math.round(line.qty * map.units * 1000) / 1000;
      const candidates = batchesFor(map.productKey, map.containerKey);
      const allocations = [];
      if (doc.docType === "invoice") {
        let need = units;
        [...candidates]
          .sort((a, b) => packedOn[a.id].localeCompare(packedOn[b.id]))
          .forEach((b) => {
            if (need <= 0) return;
            const key = `${b.id}::${map.containerKey}`;
            const take = Math.min(need, Math.max(0, avail[key] || 0));
            if (take <= 0) return;
            avail[key] = (avail[key] || 0) - take;
            need -= take;
            allocations.push({ batchId: b.id, containerKey: map.containerKey, qty: take });
          });
        allocations.forEach((a) => soldOf(batchById[a.batchId]).push({ lineId: line.lineId, docNumber: doc.number, date: doc.date, containerKey: a.containerKey, qty: a.qty }));
        const status = need > 0.0005 ? "short" : "applied";
        if (status === "short") summary.short += 1;
        summary.applied += 1;
        summary.units += units - Math.max(0, need);
        rows.push({ ...base, units, status, allocations });
      } else {
        // Customer credit note: the stock comes back on the newest batch.
        const newest = [...candidates].sort((a, b) => packedOn[b.id].localeCompare(packedOn[a.id]))[0];
        if (newest) {
          soldOf(newest).push({ lineId: line.lineId, docNumber: doc.number, date: doc.date, containerKey: map.containerKey, qty: -units });
          avail[`${newest.id}::${map.containerKey}`] = (avail[`${newest.id}::${map.containerKey}`] || 0) + units;
          allocations.push({ batchId: newest.id, containerKey: map.containerKey, qty: -units });
          summary.returned += units;
        }
        rows.push({ ...base, units, status: newest ? "applied" : "short", allocations });
        if (!newest) summary.short += 1;
      }
    });
  });

  const batchChanges = Object.entries(soldChanges)
    .filter(([id, list]) => JSON.stringify(list) !== JSON.stringify(batchById[id].xeroSold || []))
    .map(([id, xeroSold]) => ({ id, xeroSold }));
  return { rows, batchChanges, unmatched, summary };
}

// A first guess at which beer and container a Xero item is, from its code
// and name — "BC50" / "Base Camp Hazy IPA 50L keg" → Base Camp Hazy, 50L
// keg; anything mentioning 24, case or 330ml → cans, 24 to a unit.
function guessXeroItemMatch(item, beerNames) {
  const text = `${item.code} ${item.name}`.toLowerCase();
  let containerKey = "";
  let units = 1;
  if (/\b50\s*l|50l|50$|\b50\b/.test(text)) containerKey = "kegs50";
  else if (/\b30\s*l|30l|\b30\b/.test(text)) containerKey = "kegs30";
  else if (/\b20\s*l|20l|\b20\b/.test(text)) containerKey = "kegs20";
  if (/1x24|24\s*x|\bcase\b|\b24\b|24$|330/.test(text)) {
    containerKey = "cans330";
    units = /4\s*pack|4pk/.test(text) ? 4 : /6\s*pack|6pk/.test(text) ? 6 : /\bsingle\b|1x330/.test(text) ? 1 : 24;
  }
  const words = (s) => s.toLowerCase().replace(/[^a-z0-9 ]/g, " ").split(/\s+/).filter((w) => w.length > 2 && !["beer", "keg", "kegs", "case", "cans", "can", "the", "and", "ipa", "330ml", "50l", "20l", "30l"].includes(w));
  const itemWords = new Set(words(item.name));
  let best = "";
  let bestScore = 0;
  (beerNames || []).forEach((n) => {
    const score = words(n).filter((w) => itemWords.has(w)).length;
    if (score > bestScore) { best = n; bestScore = score; }
  });
  return { beerName: best, containerKey, units };
}

// A mixed pack's own available-to-sell count — how many have been put
// together minus how many have already sold. Kept separate from the
// per-beer list above since it's a different kind of "product" entirely.
function mixedPackStockList(mixedPackTypes, mixedPackAssemblies, salesOrders) {
  return (mixedPackTypes || []).map((t) => {
    const assembled = (mixedPackAssemblies || [])
      .filter((a) => a.mixedPackTypeId === t.id)
      .reduce((sum, a) => sum + a.quantity, 0);
    const sold = (salesOrders || [])
      .filter((o) => o.status !== "Draft" && o.status !== "Cancelled")
      .reduce((sum, o) => sum + (o.lines || []).filter((l) => l.mixedPackTypeId === t.id).reduce((s, l) => s + (l.qty || 0), 0), 0);
    return { ...t, assembled, available: assembled - sold };
  });
}

// Sales-driven production forecast — different from ingredientsNeededForScheduled
// above, which only forecasts raw material needs for brews already
// scheduled. This looks the other way: at current sales velocity, is a
// recipe going to run out of packaged stock before a fresh batch could
// realistically be brewed and ready? Only flags recipes that are
// actually selling (avoids nonsense suggestions for anything dormant),
// and never flags one that already has a batch in the pipeline.
function recipeDemandForecast(recipes, batches, salesOrders, windowDays = 60, leadTimeDays = 21) {
  const stockList = availableStockList(batches, salesOrders, []);
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - windowDays);
  const cutoffStr = cutoff.toISOString().slice(0, 10);

  return activeRecipesByFamily(recipes)
    .map((recipe) => {
      const recipeBatchIds = new Set(batches.filter((b) => b.recipeId === recipe.id).map((b) => b.id));
      if (recipeBatchIds.size === 0) return null;

      const currentStock = stockList
        .filter((s) => recipeBatchIds.has(s.batchId))
        .reduce((sum, s) => sum + Math.max(0, s.available), 0);

      let unitsSoldRecently = 0;
      (salesOrders || []).forEach((o) => {
        if (o.status === "Draft" || o.status === "Cancelled") return;
        if (!o.orderDate || o.orderDate < cutoffStr) return;
        (o.lines || []).forEach((l) => {
          if (recipeBatchIds.has(l.batchId)) unitsSoldRecently += l.fulfilledQty || 0;
        });
      });
      const dailyVelocity = unitsSoldRecently / windowDays;
      if (dailyVelocity <= 0) return null;

      const hasUpcomingBatch = batches.some((b) => b.recipeId === recipe.id && b.stage !== "Packaged");
      const daysOfStockRemaining = currentStock / dailyVelocity;
      const needsAttention = daysOfStockRemaining < leadTimeDays && !hasUpcomingBatch;

      return { recipe, currentStock, dailyVelocity, daysOfStockRemaining, hasUpcomingBatch, needsAttention };
    })
    .filter(Boolean)
    .sort((a, b) => a.daysOfStockRemaining - b.daysOfStockRemaining);
}

// Deterministic per-user color for the reminders calendar — same person
// always gets the same color, without needing to store one anywhere.
const USER_COLORS = ["#5C9A3C", "#D9A441", "#4AA8C9", "#B5502F", "#8E6FB5", "#5C6B54"];
function userColor(name) {
  if (!name) return "#9BA88A";
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = (hash * 31 + name.charCodeAt(i)) >>> 0;
  return USER_COLORS[hash % USER_COLORS.length];
}

const totalPackagedVolume = (batch) =>
  packagingEvents(batch).reduce((sum, e) => sum + packagedVolume(e), 0);

const remainingVolume = (batch) => {
  const rem = batch.volume - totalPackagedVolume(batch) - packagingDiscarded(batch);
  return Math.max(0, Math.round(rem * 100) / 100);
};

// What's actually still in stock is worth its real, weighted cost across
// whatever lots remain — not just current qty times the most recent price,
// which would misstate value whenever older stock was bought at a
// different price than what's most recently arrived. Falls back to the
// flat costPerUnit for items with no lot-level history (consumables, or
// anything added before lot tracking existed).
function inventoryItemValue(item) {
  if (item.lots && item.lots.length > 0) {
    return item.lots.reduce((sum, lot) => sum + (lot.remainingQty || 0) * (lot.unitCost || 0), 0);
  }
  return (item.qty || 0) * (item.costPerUnit || 0);
}

// NZ Customs alcohol excise duty rates, effective 1 July 2026 (the annual
// CPI-indexed adjustment). Source: customs.govt.nz "New excise duty rates
// for alcohol from 1 July 2026". Two different calculation bases apply
// depending on strength — most craft beer (2.5–6% ABV) is charged per
// litre of pure alcohol, not per litre of beverage.
// For excise item classification — different product types get different
// item numbers on a real Customs declaration, on top of just the ABV band.
const PRODUCT_TYPES = ["Beer", "Cider/Perry", "Wine", "Spirits", "RTD/Mixed drink", "Other"];

const NZ_EXCISE_BANDS = [
  { min: 0, max: 1.15, rate: 0, basis: "exempt" },
  { min: 1.15, max: 2.5, rate: 0.58492, basis: "beverage" },
  { min: 2.5, max: 6, rate: 38.999, basis: "alcohol" },
  { min: 6, max: 9, rate: 3.1199, basis: "beverage" },
  { min: 9, max: 14, rate: 3.8999, basis: "beverage" },
  { min: 14, max: 23, rate: 71.034, basis: "alcohol" },
  { min: 23, max: Infinity, rate: 71.034, basis: "alcohol" },
];

// The 2.5–6% beer rate (per litre of alcohol) changes every 1 July, so
// each packaging date is charged at the rate in force on that day.
const BEER_LAL_RATE_HISTORY = [
  { from: "2026-07-01", rate: 38.999 },
  { from: "2025-07-01", rate: 37.836 },
  { from: "2024-07-01", rate: 36.905 },
  { from: "0000-01-01", rate: 35.4505 },
];
function exciseRateOn(band, date) {
  if (band.basis === "alcohol" && band.min === 2.5 && date) {
    return (BEER_LAL_RATE_HISTORY.find((r) => String(date) >= r.from) || BEER_LAL_RATE_HISTORY[0]).rate;
  }
  return band.rate;
}

function exciseBandForAbv(abv) {
  return NZ_EXCISE_BANDS.find((b) => abv > b.min && abv <= b.max) || NZ_EXCISE_BANDS[0];
}

// Pae Ora (Healthy Futures) Alcohol Levy, in dollars per litre of beverage,
// by strength class, from Customs' published notices. It changes every
// 1 July. It applies to every product type, charged by strength class.
// Checked against a real TSW entry: 273.360L @ 6% in June 2026 →
// 273.360 × 0.024471 = $6.69. Excise duty itself doesn't attract GST;
// only the levy does, at 15%.
const LEVY_CLASSES = [
  { min: 1.15, max: 2.5, cls: "A" },
  { min: 2.5, max: 6, cls: "B" },
  { min: 6, max: 9, cls: "C" },
  { min: 9, max: 14, cls: "D" },
  { min: 14, max: 23, cls: "E" },
  { min: 23, max: Infinity, cls: "F" },
];
const LEVY_RATE_HISTORY = [
  { from: "2026-07-01", A: 0.008625, B: 0.02657, C: 0.046003, D: 0.057503, E: 0.095947, F: 0.218047 },
  { from: "2025-07-01", A: 0.00789, B: 0.024471, C: 0.042078, D: 0.052597, E: 0.093323, F: 0.202587 },
  { from: "2024-07-01", A: 0.00745, B: 0.023476, C: 0.039732, D: 0.049665, E: 0.086657, F: 0.185936 },
  { from: "0000-01-01", A: 0.005056, B: 0.015665, C: 0.026967, D: 0.033708, E: 0.056214, F: 0.127345 },
];
const GST_RATE = 0.15;
function levyRateOn(abv, date) {
  const c = LEVY_CLASSES.find((b) => abv > b.min && abv <= b.max);
  if (!c) return 0;
  const year = LEVY_RATE_HISTORY.find((r) => String(date || "9999") >= r.from) || LEVY_RATE_HISTORY[0];
  return year[c.cls];
}
const round2 = (n) => Math.round((n || 0) * 100) / 100;
// Levy and GST for one TSW line: worked out on the line's litres, then GST on that levy.
function lineLevy(litres, abv, date) {
  const levy = round2(litres * levyRateOn(abv, date));
  return { levy, levyGst: round2(levy * GST_RATE) };
}
// Levy and GST for a whole month's declared lines (a saved return).
function levyForDeclaredLines(lines, period) {
  let levy = 0;
  let levyGst = 0;
  (lines || []).forEach((l) => {
    if (l.litres == null || l.abv == null) return;
    const x = lineLevy(Number(l.litres), Number(l.abv), `${period}-01`);
    levy += x.levy;
    levyGst += x.levyGst;
  });
  return { levy: round2(levy), levyGst: round2(levyGst) };
}
// What a saved return actually cost: duty + levy + GST on the levy.
function returnPayable(ret) {
  if (!ret || ret.declaredDuty == null) return null;
  const duty = Number(ret.declaredDuty);
  const levy = ret.declaredLevy != null ? Number(ret.declaredLevy) : null;
  const levyGst = ret.declaredLevyGst != null ? Number(ret.declaredLevyGst) : null;
  return { duty, levy, levyGst, total: round2(duty + (levy || 0) + (levyGst || 0)) };
}
const payableText = (p) =>
  p ? `Duty $${p.duty.toFixed(2)}${p.levy != null ? ` · Levy $${p.levy.toFixed(2)} · GST on levy $${(p.levyGst || 0).toFixed(2)} · Total $${p.total.toFixed(2)}` : ""}` : "";

// One row per packaging event, since excise is calculated on what actually
// left the licensed area on a given date — a batch packaged across several
// sessions can straddle two different reporting periods.
function exciseRowsForBatches(batches, abvMethod) {
  const rows = [];
  batches.forEach((b) => {
    if (b.mergedIntoBatchId) return;
    const latest = b.og ? latestReading(b) : null;
    const measured = b.og && latest && latest.gravity != null ? calcABV(b.og, latest.gravity) : null;
    const measuredAbv = measured != null && measured > 0 ? measured : null;
    // Label strength is a genuine Customs-recognised method for smaller
    // beer producers (≤2 million L/year, with conditions) — falls back to
    // measured and flags it if no label ABV has been recorded for a batch.
    // eligibleForLabel tracks whether label mode even applies to this
    // product (beer only) — separate from usedLabel, which tracks whether
    // a real label value was actually available and used, so a non-beer
    // row can never be mistaken for "used label" just because it wasn't
    // a fallback either.
    const eligibleForLabel = abvMethod === "label" && (b.productType || "Beer") === "Beer";
    const usedLabel = eligibleForLabel && !!b.labelAbv;
    const usedFallback = eligibleForLabel && !b.labelAbv;
    const abv = usedLabel ? Number(b.labelAbv) : measuredAbv;
    // No label strength and no gravity to measure from — left out here and
    // flagged by the self-audit instead.
    if (abv == null || abv <= 0) return;
    const band = exciseBandForAbv(abv);
    packagingEvents(b).forEach((e) => {
      const volumeL = packagedVolume(e);
      if (volumeL <= 0) return;
      const rate = exciseRateOn(band, e.date);
      const duty = band.basis === "alcohol" ? volumeL * (abv / 100) * rate : band.basis === "beverage" ? volumeL * rate : 0;
      const { levy, levyGst } = lineLevy(volumeL, abv, e.date);
      rows.push({ batchId: b.id, batchName: b.name, batchNumber: b.number, productType: b.productType || "Beer", date: e.date, event: e, abv, measuredAbv, labelAbv: b.labelAbv, usedLabel, usedFallback, volumeL, band, duty, levy, levyGst });
    });
  });
  return rows.sort((a, b) => (b.date || "").localeCompare(a.date || ""));
}

// ─── Excise self-audit ──────────────────────────────────────────────────────
// Duty here is declared at packaging (that's how this brewery files), so
// each month's TSW return should match what was packaged that month. The
// check compares litres and litres of alcohol (LAL), never dollars — duty
// rates change every 1 July, so a dollar comparison against today's rates
// would flag every month filed under an older rate.

// TSW truncates LAL to 3 decimals rather than rounding (confirmed against
// a real entry), so the expected figure has to be built the same way.
// The tiny nudge stops floating-point error (4.6079999…) cutting a whole 0.001 off.
const exciseLal = (volumeL, abv) => Math.floor(volumeL * (abv / 100) * 1000 + 1e-6) / 1000;
const round3 = (n) => Math.round((n || 0) * 1000) / 1000;

function addMonthsToKey(key, n) {
  const [y, m] = key.split("-").map(Number);
  const d = new Date(y, m - 1 + n, 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

// Customs' standard due date for a monthly excise return is the 20th of
// the following month — shown as a guide, since arrangements can differ.
const exciseDueDate = (period) => `${addMonthsToKey(period, 1)}-20`;

// Differences this small are rounding, not a real discrepancy.
const litresTolerance = (expected) => Math.max(1, Math.abs(expected) * 0.005);
const lalTolerance = (expected) => Math.max(0.05, Math.abs(expected) * 0.005);

function exciseAuditMonths({ batches, abvMethod, exciseReturns, exciseItemCodes, todayStr }) {
  const rows = exciseRowsForBatches(batches, abvMethod);
  const byMonth = {};
  const ensure = (k) => byMonth[k] || (byMonth[k] = { litres: 0, lal: 0, rows: [], noAbv: [] });
  let undated = 0;

  rows.forEach((r) => {
    const k = monthKeyFromDate(r.date);
    if (k === "unknown") { undated += 1; return; }
    const m = ensure(k);
    m.litres += r.volumeL;
    m.lal += exciseLal(r.volumeL, r.abv);
    m.rows.push(r);
  });

  // exciseRowsForBatches skips a batch entirely when it has no measured
  // ABV — that beer is still packaged and still owes duty, so it's the
  // single most important thing for the audit to surface.
  const counted = new Set(rows.map((r) => r.batchId));
  batches.forEach((b) => {
    if (counted.has(b.id)) return;
    packagingEvents(b).forEach((e) => {
      const v = packagedVolume(e);
      if (v <= 0) return;
      const k = monthKeyFromDate(e.date);
      if (k === "unknown") { undated += 1; return; }
      ensure(k).noAbv.push({ batchName: b.name, batchNumber: b.number, date: e.date, volumeL: v });
    });
  });

  const returnsByPeriod = {};
  exciseReturns.forEach((r) => (returnsByPeriod[r.period] = r));

  const keys = [...Object.keys(byMonth), ...Object.keys(returnsByPeriod)].sort();
  if (keys.length === 0) return { months: [], undated };
  const thisMonth = todayStr.slice(0, 7);
  const last = keys[keys.length - 1] > thisMonth ? keys[keys.length - 1] : thisMonth;
  const months = [];

  for (let k = keys[0]; k <= last; k = addMonthsToKey(k, 1)) {
    const m = byMonth[k] || { litres: 0, lal: 0, rows: [], noAbv: [] };
    const ret = returnsByPeriod[k] || null;
    const appLitres = round3(m.litres);
    const appLal = round3(m.lal);
    const due = exciseDueDate(k);
    const notDueYet = todayStr <= due;
    const issues = [];
    const red = (text) => issues.push({ level: "red", text });
    const amber = (text) => issues.push({ level: "amber", text });
    const hasActivity = appLitres > 0 || m.noAbv.length > 0;

    if (m.noAbv.length > 0) {
      const v = round3(m.noAbv.reduce((s, x) => s + x.volumeL, 0));
      red(`${v} L packaged with no ABV recorded (${m.noAbv.map((x) => x.batchName).join(", ")}) — log a final gravity so it's counted.`);
    }
    const fallbacks = [...new Set(m.rows.filter((r) => r.usedFallback).map((r) => r.batchName))];
    if (fallbacks.length > 0) amber(`No label ABV set for ${fallbacks.join(", ")} — measured ABV used instead.`);
    const types = [...new Set(m.rows.map((r) => r.productType))];
    const noCode = types.filter((t) => !exciseItemCodes.find((e) => e.productType === t)?.itemNumber);
    if (noCode.length > 0) amber(`No excise item number set for ${noCode.join(", ")}.`);

    let litresDiff = null;
    let lalDiff = null;
    let status;

    if (!ret) {
      if (!hasActivity) status = "nil";
      else if (notDueYet) status = "notdue";
      else {
        red("Beer was packaged this month but no return has been recorded here.");
        status = "missing";
      }
    } else {
      const explained = !!(ret.varianceExplanation || "").trim();
      if (ret.declaredLitres == null && ret.declaredLal == null) {
        amber("Return recorded, but no declared litres or LAL entered yet.");
      }
      if (ret.declaredLitres != null) {
        litresDiff = round3(ret.declaredLitres - appLitres);
        if (Math.abs(litresDiff) > litresTolerance(appLitres)) {
          const text = `Declared ${ret.declaredLitres} L but ${appLitres} L was packaged (${litresDiff > 0 ? "+" : ""}${litresDiff} L).`;
          explained ? amber(`${text} Explained.`) : red(text);
        }
      }
      if (ret.declaredLal != null) {
        lalDiff = round3(ret.declaredLal - appLal);
        if (Math.abs(lalDiff) > lalTolerance(appLal)) {
          const text = `Declared ${ret.declaredLal} LAL but records give ${appLal} LAL (${lalDiff > 0 ? "+" : ""}${lalDiff}).`;
          explained ? amber(`${text} Explained.`) : red(text);
        }
      }
      if ((ret.declaredLines || []).length > 0) {
        const offRows = exciseAbvComparison(m.rows, ret.declaredLines).filter((r) => r.off);
        if (offRows.length > 0) {
          const detail = offRows.slice(0, 3).map((r) => `${r.abv === "?" ? "unknown ABV" : `${r.abv}%`}: packaged ${Math.round(r.packedL)} L, declared ${Math.round(r.declaredL)} L`).join("; ");
          amber(`By strength — ${detail}${offRows.length > 3 ? `; and ${offRows.length - 3} more` : ""}.`);
        }
      }
      if (ret.appLitresAtFiling != null && Math.abs(ret.appLitresAtFiling - appLitres) > 0.01) {
        amber(`Packaging records for this month changed after the return was recorded (was ${ret.appLitresAtFiling} L, now ${appLitres} L).`);
      }
      // TSW's return screens don't show a lodgement date or entry number,
      // so their absence isn't flagged — only a known late filing is.
      if (ret.filedDate && ret.filedDate > due) amber(`Filed ${ret.filedDate}, after the usual due date of ${due}.`);
      if (!(ret.screenshotPaths || []).length) amber("No TSW screenshot attached as evidence.");
      status = issues.some((i) => i.level === "red") ? "attention" : issues.length > 0 ? "check" : "ok";
    }
    if (status === "nil" && issues.length > 0) status = "check";

    months.push({ period: k, appLitres, appLal, rows: m.rows, noAbv: m.noAbv, ret, litresDiff, lalDiff, due, issues, status });
  }
  return { months: months.reverse(), undated };
}

const AUDIT_STATUS = {
  ok: { label: "Matches", color: "#3F7A28", bg: "#E4F0DA" },
  check: { label: "Check notes", color: "#8A6D0B", bg: "#FBF0CC" },
  attention: { label: "Needs attention", color: "#B5502F", bg: "#F8DDD3" },
  missing: { label: "No return", color: "#B5502F", bg: "#F8DDD3" },
  notdue: { label: "Not due yet", color: "#5C6B54", bg: "#EBE8D6" },
  nil: { label: "Nothing packaged", color: "#9BA88A", bg: "#F0EDE0" },
};

// Screenshots straight off an iPad are large PNGs. Shrinking to a sharp
// JPEG keeps them well inside the image limit for reading, makes uploads
// quick, and is still perfectly legible as stored evidence.
function shrinkImageFile(file, maxSide = 2400) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      const scale = Math.min(1, maxSide / Math.max(img.width, img.height));
      const canvas = document.createElement("canvas");
      canvas.width = Math.round(img.width * scale);
      canvas.height = Math.round(img.height * scale);
      canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
      URL.revokeObjectURL(url);
      canvas.toBlob(
        (blob) => {
          if (!blob) return reject(new Error("Couldn't process that image."));
          const reader = new FileReader();
          reader.onload = () => resolve({ blob, base64: String(reader.result).split(",")[1], previewUrl: URL.createObjectURL(blob) });
          reader.onerror = () => reject(new Error("Couldn't read that image."));
          reader.readAsDataURL(blob);
        },
        "image/jpeg",
        0.88
      );
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error("That file isn't an image this device can open.")); };
    img.src = url;
  });
}

// A TSW line doesn't always show all three figures. Any two of litres,
// LAL and ABV give the third: LAL = litres × ABV%, litres = LAL ÷ ABV%,
// ABV = LAL ÷ litres. Worked-out figures are flagged so the review
// screen can show which ones weren't read straight off the screenshot.
// LAL follows TSW's truncation; litres derived from a truncated LAL can be
// out by a fraction of a litre, which sits inside the matching tolerance.
function completeTswLine(line) {
  const out = { ...line, derived: [] };
  const has = (v) => v != null && Number.isFinite(v) && v > 0;
  if (!has(out.lal) && has(out.litres) && has(out.abv)) {
    out.lal = exciseLal(out.litres, out.abv);
    out.derived.push("lal");
  }
  if (!has(out.litres) && has(out.lal) && has(out.abv)) {
    out.litres = round3(out.lal / (out.abv / 100));
    out.derived.push("litres");
  }
  if (!has(out.abv) && has(out.lal) && has(out.litres)) {
    out.abv = Math.round((out.lal / out.litres) * 100 * 100) / 100;
    out.derived.push("abv");
  }
  return out;
}

// Reads the images out of a .zip without any extra library — the zip's
// central directory lists every file, and deflated entries are unpacked
// with the browser's own DecompressionStream (Safari 16.4+, Chrome, Firefox).
// Folders, Mac "__MACOSX" metadata and non-image files are skipped.
const ZIP_IMAGE_TYPES = { png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", heic: "image/heic", heif: "image/heif", webp: "image/webp", gif: "image/gif" };

async function imagesFromZip(zipFile) {
  const buf = new Uint8Array(await zipFile.arrayBuffer());
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  // End-of-central-directory record sits in the last 64 KB of the file.
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i -= 1) {
    if (view.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) throw new Error(`${zipFile.name} isn't a zip file this can open.`);
  const count = view.getUint16(eocd + 10, true);
  let ptr = view.getUint32(eocd + 16, true);
  const decoder = new TextDecoder();
  const out = [];
  for (let n = 0; n < count; n += 1) {
    if (view.getUint32(ptr, true) !== 0x02014b50) break;
    const method = view.getUint16(ptr + 10, true);
    const compSize = view.getUint32(ptr + 20, true);
    const nameLen = view.getUint16(ptr + 28, true);
    const extraLen = view.getUint16(ptr + 30, true);
    const commentLen = view.getUint16(ptr + 32, true);
    const localOffset = view.getUint32(ptr + 42, true);
    const name = decoder.decode(buf.subarray(ptr + 46, ptr + 46 + nameLen));
    ptr += 46 + nameLen + extraLen + commentLen;

    const base = name.split("/").pop();
    const ext = (base.split(".").pop() || "").toLowerCase();
    if (name.endsWith("/") || name.startsWith("__MACOSX/") || base.startsWith(".") || !ZIP_IMAGE_TYPES[ext]) continue;

    const localNameLen = view.getUint16(localOffset + 26, true);
    const localExtraLen = view.getUint16(localOffset + 28, true);
    const start = localOffset + 30 + localNameLen + localExtraLen;
    const raw = buf.subarray(start, start + compSize);
    let data;
    if (method === 0) data = raw;
    else if (method === 8) {
      if (typeof DecompressionStream === "undefined") throw new Error("This device's browser can't unzip files — update iPadOS, or pick the screenshots directly.");
      const stream = new Blob([raw]).stream().pipeThrough(new DecompressionStream("deflate-raw"));
      data = new Uint8Array(await new Response(stream).arrayBuffer());
    } else continue;
    const blob = new Blob([data], { type: ZIP_IMAGE_TYPES[ext] });
    blob.name = base;
    out.push(blob);
  }
  // Keep the zip's own name order, so screenshots named by month read in order.
  return out.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));
}

const isZipFile = (f) => /\.zip$/i.test(f.name || "") || f.type === "application/zip" || f.type === "application/x-zip-compressed";

// Two lines count as the same line only when every figure matches. The
// same line on two different screenshots is the overlap from scrolling
// (or the same page picked twice), so it's counted once; identical lines
// on one screenshot are genuinely separate entries and both stay.
const sameTswLine = (a, b) =>
  String(a.itemCode || "") === String(b.itemCode || "") && a.litres === b.litres && a.lal === b.lal && (a.abv ?? null) === (b.abv ?? null);

function mergeTswLines(base, extra) {
  const out = [...base];
  extra.forEach((l) => {
    if (!out.some((x) => x.source !== l.source && sameTswLine(x, l))) out.push(l);
  });
  return out;
}

function tswTotals(lines) {
  const sum = (k, dp) => (lines.some((l) => l[k] != null) ? Math.round(lines.reduce((acc, l) => acc + (l[k] || 0), 0) * 10 ** dp) / 10 ** dp : null);
  return { litres: sum("litres", 3), lal: sum("lal", 3), duty: sum("duty", 2) };
}

// One TSW return often runs over two or three screens, and only the first
// usually shows the month. Screenshots are matched to a return by entry
// number first, then by month, and a page with neither is treated as the
// next page of the screenshot before it.
function groupScreenshotReadings(readings) {
  const norm = (v) => String(v || "").replace(/\s/g, "").toUpperCase();
  const groups = [];
  let prev = null;
  readings.forEach((r, idx) => {
    let g = null;
    if (r.entryNumber) g = groups.find((x) => x.entryNumber && norm(x.entryNumber) === norm(r.entryNumber)) || null;
    if (!g && r.period) g = groups.find((x) => x.period === r.period) || null;
    if (!g && !r.period && prev) g = prev;
    if (!g) {
      g = { period: "", images: [], lines: [], entryNumber: "", filedDate: "", totalDuty: null, notes: [] };
      groups.push(g);
    }
    if (!g.period && r.period) g.period = r.period;
    g.images.push(r.image);
    g.lines = mergeTswLines(g.lines, (r.lines || []).map((l) => ({ ...completeTswLine(l), source: `img${idx}` })));
    if (!g.entryNumber && r.entryNumber) g.entryNumber = r.entryNumber;
    if (!g.filedDate && r.filedDate) g.filedDate = r.filedDate;
    // A grand total is usually on the last page — keep the latest one seen
    // rather than adding up the same total read off two pages.
    if (r.totalDuty != null) g.totalDuty = r.totalDuty;
    if (r.notes) g.notes.push(r.notes);
    prev = g;
  });
  return groups;
}

// Lines up what was packaged against what was declared, strength by
// strength. TSW lists each ABV as its own line, so this shows which beer
// a difference comes from — something the monthly totals can hide when
// an over and an under cancel out.
function exciseAbvComparison(rows, declaredLines) {
  const key = (abv) => (abv == null || !Number.isFinite(abv) ? "?" : (Math.round(abv * 10) / 10).toFixed(1));
  const map = {};
  const get = (k) => map[k] || (map[k] = { abv: k, packedL: 0, packedLal: 0, beers: new Set(), declaredL: 0, declaredLal: 0, descriptions: new Set() });
  rows.forEach((r) => {
    const g = get(key(r.abv));
    g.packedL += r.volumeL;
    g.packedLal += exciseLal(r.volumeL, r.abv);
    g.beers.add(r.batchName);
  });
  (declaredLines || []).forEach((l) => {
    const g = get(key(l.abv));
    g.declaredL += l.litres || 0;
    g.declaredLal += l.lal || 0;
    if (l.description) g.descriptions.add(l.description);
  });
  return Object.values(map)
    .map((g) => {
      const packedL = round3(g.packedL);
      const declaredL = round3(g.declaredL);
      return {
        ...g,
        packedL,
        declaredL,
        packedLal: round3(g.packedLal),
        declaredLal: round3(g.declaredLal),
        beers: [...g.beers],
        descriptions: [...g.descriptions],
        diff: round3(declaredL - packedL),
        off: Math.abs(declaredL - packedL) > litresTolerance(packedL),
      };
    })
    .sort((a, b) => (a.abv === "?") - (b.abv === "?") || Number(a.abv) - Number(b.abv));
}

function monthKeyFromDate(dateStr) {
  return dateStr && dateStr.length >= 7 ? dateStr.slice(0, 7) : "unknown";
}

function monthLabelFromKey(key) {
  if (key === "unknown") return "Unknown date";
  const [y, m] = key.split("-").map(Number);
  return new Date(y, m - 1, 1).toLocaleDateString(undefined, { month: "long", year: "numeric" });
}

// Groups every packaging event across every batch by month, with a running
// volume/container total per month and a per-batch breakdown within it.
function packagingByMonth(batches) {
  const groups = {};
  batches.forEach((b) => {
    packagingEvents(b).forEach((e) => {
      const key = monthKeyFromDate(e.date);
      if (!groups[key]) groups[key] = { volume: 0, counts: {}, batches: {} };
      const vol = packagedVolume(e);
      groups[key].volume = Math.round((groups[key].volume + vol) * 100) / 100;
      CONTAINERS.forEach((c) => {
        groups[key].counts[c.key] = (groups[key].counts[c.key] || 0) + (e[c.key] || 0);
      });
      if (!groups[key].batches[b.id]) groups[key].batches[b.id] = { id: b.id, name: b.name, number: b.number, volume: 0 };
      groups[key].batches[b.id].volume = Math.round((groups[key].batches[b.id].volume + vol) * 100) / 100;
    });
  });
  return Object.keys(groups)
    .sort()
    .reverse()
    .map((key) => ({ key, label: monthLabelFromKey(key), ...groups[key], batches: Object.values(groups[key].batches) }));
}

// A tank is occupied if some batch is sitting on it and hasn't been fully
// packaged out yet. excludeBatchId lets a batch ignore its own current
// assignment when checking whether it can stay put.
// A batch can sit on a single tank (tankId) or be split across several
// (splitTanks) — this returns every tank id it currently occupies either way.
// Natural sort: "Tank 2" before "Tank 10", numeric chunks compared as
// numbers rather than character-by-character; falls back to plain
// alphabetical for tanks with non-numbered names.
function compareTankNames(a, b) {
  const chunks = /(\d+)|(\D+)/g;
  const ax = (a || "").match(chunks) || [];
  const bx = (b || "").match(chunks) || [];
  const len = Math.max(ax.length, bx.length);
  for (let i = 0; i < len; i++) {
    const av = ax[i] ?? "";
    const bv = bx[i] ?? "";
    const bothNumeric = /^\d+$/.test(av) && /^\d+$/.test(bv);
    const cmp = bothNumeric ? Number(av) - Number(bv) : av.localeCompare(bv);
    if (cmp !== 0) return cmp;
  }
  return 0;
}
const sortedTanks = (tanks) => [...tanks].sort((a, b) => compareTankNames(a.name, b.name));

const COMMON_FAULTS = [
  "Diacetyl",
  "DMS",
  "Acetaldehyde",
  "Oxidation",
  "Infection/Sour",
  "Phenolic (band-aid)",
  "Astringency",
  "Hop creep",
  "Sulfur",
  "Yeast bite",
];
const FAULT_SEVERITY_COLOR = { Low: "#D9A441", Medium: "#E08A3C", High: "#B5502F" };
const FAULT_SEVERITY_NEXT = { none: "Low", Low: "Medium", Medium: "High", High: null };

// batch.faults is a log of dated entries (multiple per fault name allowed,
// one per day it was reassessed) so a fault noticed one day and gone the
// next doesn't erase the earlier observation. This collapses it down to
// just the latest entry per fault — i.e. "what's the current read."
function currentFaults(batch) {
  const byName = {};
  (batch.faults || []).forEach((f) => {
    if (!byName[f.fault] || f.date > byName[f.fault].date) byName[f.fault] = f;
  });
  return Object.values(byName);
}

// Same logic as currentFaults above, but for a plain faults array rather
// than a whole batch — used for one split-tank side's own faults list,
// where there's no batch-shaped object to pass in.
function currentFaultsList(faultsList) {
  const byName = {};
  (faultsList || []).forEach((f) => {
    if (!byName[f.fault] || f.date > byName[f.fault].date) byName[f.fault] = f;
  });
  return Object.values(byName);
}

function batchTankIds(batch) {
  // A brew day merged into another batch no longer has a tank of its own —
  // its wort went into the batch it was merged into.
  if (batch.mergedIntoBatchId) return [];
  if (batch.splitTanks && batch.splitTanks.length > 0) return batch.splitTanks.map((t) => t.tankId);
  if (batch.tankId) return [batch.tankId];
  return [];
}

// Real lead time and spend from actual received orders — not a manually
// typed guess. Matches by supplier name, the same way every other PO
// lookup in the app already does, since a PO stores the supplier as
// plain text rather than a reference id.
function supplierPerformance(supplierName, purchaseOrders) {
  const received = (purchaseOrders || []).filter((po) => po.supplier === supplierName && po.status === "Received" && po.receivedDate);
  if (received.length === 0) return null;

  const leadTimes = received.map((po) => daysBetween(po.orderDate, po.receivedDate)).filter((d) => d >= 0);
  const avgLeadTimeDays = leadTimes.length > 0 ? Math.round((leadTimes.reduce((sum, d) => sum + d, 0) / leadTimes.length) * 10) / 10 : null;
  const totalSpend = received.reduce((sum, po) => {
    const lineTotal = (po.lines || []).reduce((s, l) => s + (Number(l.costPerUnit) || 0) * (Number(l.qty) || 0), 0);
    return sum + lineTotal + (po.deliveryCost || 0);
  }, 0);
  const lastOrderDate = received.reduce((latest, po) => (!latest || po.orderDate > latest ? po.orderDate : latest), null);

  return { poCount: received.length, avgLeadTimeDays, totalSpend, lastOrderDate };
}

function batchTankSummary(batch) {
  if (batch.splitTanks && batch.splitTanks.length > 0) {
    return batch.splitTanks.map((t) => `${t.tankName} (${t.volume}L)`).join(" + ");
  }
  return batch.tankName || "";
}

// Shows sub-1kg amounts in grams instead — 0.05kg is much easier to read as 50g.
function formatQty(qty, unit) {
  const n = Number(qty);
  if (unit === "kg" && n > 0 && n < 1) {
    return `${Math.round(n * 1000)}g`;
  }
  const display = Number.isInteger(n) ? n : Math.round(n * 100) / 100;
  return `${display} ${unit}`;
}

// Groups recipes by family and picks the one to actually use for each —
// whichever version is explicitly pinned as active, or the latest if none is.
function activeRecipesByFamily(recipes) {
  const groups = {};
  recipes.forEach((r) => {
    const fam = r.familyId || r.id;
    if (!groups[fam]) groups[fam] = [];
    groups[fam].push(r);
  });
  return Object.values(groups).map((versions) => {
    const pinned = versions.find((v) => v.isActive);
    if (pinned) return pinned;
    return versions.reduce((a, b) => ((b.version || 1) > (a.version || 1) ? b : a));
  });
}

function tankIsOccupied(batches, tankId, excludeBatchId) {
  return batches.some((b) => {
    if (!batchTankIds(b).includes(tankId)) return false;
    if (excludeBatchId && b.id === excludeBatchId) return false;
    const fullyDone = b.stage === "Packaged" && remainingVolume(b) === 0;
    return !fullyDone;
  });
}

function occupyingBatch(batches, tankId, excludeBatchId) {
  const candidates = batches.filter((b) => {
    if (!batchTankIds(b).includes(tankId)) return false;
    if (excludeBatchId && b.id === excludeBatchId) return false;
    const fullyDone = b.stage === "Packaged" && remainingVolume(b) === 0;
    return !fullyDone;
  });
  if (candidates.length === 0) return undefined;
  // A tank can genuinely have both something actively in it AND a future
  // brew already queued up for after it's out — scheduling deliberately
  // allows that. Whatever's physically in the tank right now should
  // always win here; only fall back to a scheduled one if nothing has
  // actually started yet. Without this, batch order (not reality) would
  // decide which one showed.
  return candidates.find((b) => b.startDate <= today()) || candidates[0];
}

function aggregatePackagingCounts(batch) {
  const totals = {};
  CONTAINERS.forEach((c) => (totals[c.key] = 0));
  packagingEvents(batch).forEach((e) => CONTAINERS.forEach((c) => (totals[c.key] += e[c.key] || 0)));
  return totals;
}

const BP_TANK_PATH = "M11 5 Q9 5 9 7 V21.5 L18.3 33.2 Q19 34 19.7 33.2 L29 21.5 V7 Q29 5 27 5 Z";

