// Live available-to-sell stock, per beer and container — the same numbers
// the order picker already uses, just surfaced as its own page. Stays in
// sync automatically: packaging a batch adds to it, confirming/fulfilling
// an order subtracts, cancelling an order gives it straight back.
function MixedPackTypeModal({ products, editingType, onClose, onSave }) {
  const [name, setName] = useState(editingType?.name || "");
  const [totalUnits, setTotalUnits] = useState(editingType ? String(editingType.totalUnits) : "6");
  const [mode, setMode] = useState(editingType?.mode || "flexible");
  const [price, setPrice] = useState(editingType?.price != null ? String(editingType.price) : "");
  const [lines, setLines] = useState(
    editingType?.fixedComposition?.length
      ? editingType.fixedComposition.map((l) => ({ id: uid(), ...l }))
      : []
  );

  const lineTotal = lines.reduce((sum, l) => sum + (Number(l.qty) || 0), 0);

  const addLine = () => setLines((prev) => [...prev, { id: uid(), productKey: "", qty: 1 }]);
  const updateLine = (id, patch) => setLines((prev) => prev.map((l) => (l.id === id ? { ...l, ...patch } : l)));
  const removeLine = (id) => setLines((prev) => prev.filter((l) => l.id !== id));

  const submit = () => {
    if (!name.trim() || !totalUnits || Number(totalUnits) <= 0) return;
    if (mode === "fixed" && lines.length === 0) return;
    const fixedComposition =
      mode === "fixed"
        ? lines
            .filter((l) => l.productKey)
            .map((l) => {
              const p = products.find((pr) => pr.key === l.productKey);
              return { batchName: p?.batchName, containerKey: p?.containerKey, containerLabel: p?.containerLabel, qty: Number(l.qty) || 0 };
            })
        : [];
    onSave({
      id: editingType?.id || uid(),
      name: name.trim(),
      totalUnits: Number(totalUnits),
      mode,
      fixedComposition,
      price: price === "" ? null : Number(price),
    });
    onClose();
  };

  return (
    <Modal title={editingType ? "Edit mixed pack" : "New mixed pack type"} onClose={onClose}>
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        <TextField label="Name" value={name} onChange={setName} placeholder="e.g. Variety 6-pack" />
        <div style={{ display: "flex", gap: 10 }}>
          <div style={{ flex: 1 }}>
            <NumberField label="Total units" value={totalUnits} onChange={setTotalUnits} step="1" />
          </div>
          <div style={{ flex: 1 }}>
            <NumberField label="Price (optional)" value={price} onChange={setPrice} step="0.01" />
          </div>
        </div>

        <div>
          <div style={{ color: "#9BA88A", fontSize: 11, marginBottom: 6 }}>Composition</div>
          <div style={{ display: "flex", border: "1px solid #DDE0C8", borderRadius: 4, overflow: "hidden" }}>
            {[
              ["fixed", "Fixed — always the same"],
              ["flexible", "Flexible — pick each time"],
            ].map(([m, label]) => (
              <button
                key={m}
                onClick={() => setMode(m)}
                style={{
                  flex: 1,
                  background: mode === m ? "#5C9A3C" : "#F5F1E4",
                  border: "none",
                  padding: "9px",
                  color: mode === m ? "#16191A" : "#5C6B54",
                  fontFamily: "'Inter', sans-serif",
                  fontSize: 12.5,
                  cursor: "pointer",
                }}
              >
                {label}
              </button>
            ))}
          </div>
        </div>

        {mode === "fixed" && (
          <div>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {lines.map((l) => (
                <div key={l.id} style={{ display: "flex", gap: 8, alignItems: "center" }}>
                  <select
                    value={l.productKey}
                    onChange={(e) => updateLine(l.id, { productKey: e.target.value })}
                    style={{ flex: 1, boxSizing: "border-box", background: "#F5F1E4", border: "1px solid #DDE0C8", borderRadius: 4, padding: "8px 10px", color: "#2A3324", fontFamily: "'Inter', sans-serif", fontSize: 13 }}
                  >
                    <option value="">Pick a beer…</option>
                    {products.map((p) => (
                      <option key={p.key} value={p.key}>
                        {p.label}
                      </option>
                    ))}
                  </select>
                  <input
                    type="number"
                    min="1"
                    value={l.qty}
                    onChange={(e) => updateLine(l.id, { qty: e.target.value })}
                    style={{ width: 60, boxSizing: "border-box", background: "#F5F1E4", border: "1px solid #DDE0C8", borderRadius: 4, padding: "8px", color: "#2A3324", fontFamily: "'JetBrains Mono', monospace", fontSize: 13, textAlign: "center" }}
                  />
                  <button onClick={() => removeLine(l.id)} aria-label="Remove" style={{ background: "none", border: "none", color: "#9BA88A", cursor: "pointer", padding: 4 }}>
                    <Trash2 size={14} />
                  </button>
                </div>
              ))}
            </div>
            <button
              onClick={addLine}
              style={{ marginTop: 8, background: "none", border: "1px dashed #C9D1AC", borderRadius: 5, padding: "8px", width: "100%", color: "#5C6B54", fontFamily: "'Inter', sans-serif", fontSize: 12.5, cursor: "pointer" }}
            >
              + Add beer
            </button>
            <div style={{ color: lineTotal === Number(totalUnits) ? "#5C9A3C" : "#B5502F", fontSize: 12, marginTop: 8 }}>
              {lineTotal} of {totalUnits || 0} units set
            </div>
          </div>
        )}

        <button
          onClick={submit}
          style={{ background: "#5C9A3C", border: "none", borderRadius: 5, padding: "12px", color: "#16191A", fontFamily: "'Oswald', sans-serif", fontWeight: 500, fontSize: 15, letterSpacing: "0.03em", cursor: "pointer" }}
        >
          Save
        </button>
      </div>
    </Modal>
  );
}

function AssembleMixedPackModal({ mixedPackType, availableStock, onClose, onSave }) {
  const [quantity, setQuantity] = useState("1");
  const [flexLines, setFlexLines] = useState([{ id: uid(), productKey: "", qtyPerPack: 1 }]);

  const products = availableStock
    .filter((s) => s.available > 0)
    .map((s) => ({ key: `${s.batchId}::${s.containerKey}`, label: `${s.batchName} — ${s.containerLabel}`, available: s.available, ...s }));

  const isFixed = mixedPackType.mode === "fixed";

  // Fixed mode: automatically find a real, currently-in-stock batch that
  // matches each line in the recipe — the recipe says "an IPA can", not
  // "batch #47's IPA can", since which specific batch is available
  // changes over time.
  const resolvedFixed = isFixed
    ? mixedPackType.fixedComposition.map((line) => {
        const match = availableStock.find((s) => s.batchName === line.batchName && s.containerKey === line.containerKey && s.available > 0);
        return match ? { ...line, batchId: match.batchId, available: match.available } : { ...line, batchId: null, available: 0 };
      })
    : [];
  const fixedShortfall = resolvedFixed.filter((l) => !l.batchId || l.available < l.qty * Number(quantity || 1));

  const flexTotal = flexLines.reduce((sum, l) => sum + (Number(l.qtyPerPack) || 0), 0);
  const addFlexLine = () => setFlexLines((prev) => [...prev, { id: uid(), productKey: "", qtyPerPack: 1 }]);
  const updateFlexLine = (id, patch) => setFlexLines((prev) => prev.map((l) => (l.id === id ? { ...l, ...patch } : l)));
  const removeFlexLine = (id) => setFlexLines((prev) => prev.filter((l) => l.id !== id));

  const canSubmit = isFixed
    ? fixedShortfall.length === 0 && Number(quantity) > 0
    : flexTotal === mixedPackType.totalUnits && flexLines.every((l) => l.productKey) && Number(quantity) > 0;

  const submit = () => {
    if (!canSubmit) return;
    const composition = isFixed
      ? resolvedFixed.map((l) => ({ batchId: l.batchId, batchName: l.batchName, containerKey: l.containerKey, containerLabel: l.containerLabel, qtyPerPack: l.qty }))
      : flexLines.map((l) => {
          const p = products.find((pr) => pr.key === l.productKey);
          return { batchId: p.batchId, batchName: p.batchName, containerKey: p.containerKey, containerLabel: p.containerLabel, qtyPerPack: Number(l.qtyPerPack) };
        });
    onSave({ quantity: Number(quantity), composition });
    onClose();
  };

  return (
    <Modal title={`Assemble ${mixedPackType.name}`} onClose={onClose}>
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        <NumberField label="How many packs to assemble" value={quantity} onChange={setQuantity} step="1" />

        {isFixed ? (
          <div>
            <div style={{ color: "#9BA88A", fontSize: 11, marginBottom: 6 }}>This pack's recipe</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {resolvedFixed.map((l, i) => {
                const short = !l.batchId || l.available < l.qty * Number(quantity || 1);
                return (
                  <div
                    key={i}
                    style={{ display: "flex", justifyContent: "space-between", padding: "8px 10px", background: short ? "#FBE5D2" : "#F8F5EA", border: `1px solid ${short ? "#E3B37A" : "#EBE8D6"}`, borderRadius: 5, fontSize: 13 }}
                  >
                    <span style={{ color: "#2A3324" }}>
                      {l.qty} × {l.batchName || "—"} ({l.containerLabel})
                    </span>
                    <span style={{ color: short ? "#B5502F" : "#9BA88A", fontSize: 11.5 }}>
                      {l.batchId ? `${l.available} available` : "not currently in stock"}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>
        ) : (
          <div>
            <div style={{ color: "#9BA88A", fontSize: 11, marginBottom: 6 }}>
              Build this pack — {flexTotal} of {mixedPackType.totalUnits} units picked
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {flexLines.map((l) => (
                <div key={l.id} style={{ display: "flex", gap: 8, alignItems: "center" }}>
                  <select
                    value={l.productKey}
                    onChange={(e) => updateFlexLine(l.id, { productKey: e.target.value })}
                    style={{ flex: 1, boxSizing: "border-box", background: "#F5F1E4", border: "1px solid #DDE0C8", borderRadius: 4, padding: "8px 10px", color: "#2A3324", fontFamily: "'Inter', sans-serif", fontSize: 13 }}
                  >
                    <option value="">Pick a beer…</option>
                    {products.map((p) => (
                      <option key={p.key} value={p.key}>
                        {p.label} ({p.available} available)
                      </option>
                    ))}
                  </select>
                  <input
                    type="number"
                    min="1"
                    value={l.qtyPerPack}
                    onChange={(e) => updateFlexLine(l.id, { qtyPerPack: e.target.value })}
                    style={{ width: 60, boxSizing: "border-box", background: "#F5F1E4", border: "1px solid #DDE0C8", borderRadius: 4, padding: "8px", color: "#2A3324", fontFamily: "'JetBrains Mono', monospace", fontSize: 13, textAlign: "center" }}
                  />
                  <button onClick={() => removeFlexLine(l.id)} aria-label="Remove" style={{ background: "none", border: "none", color: "#9BA88A", cursor: "pointer", padding: 4 }}>
                    <Trash2 size={14} />
                  </button>
                </div>
              ))}
            </div>
            <button
              onClick={addFlexLine}
              style={{ marginTop: 8, background: "none", border: "1px dashed #C9D1AC", borderRadius: 5, padding: "8px", width: "100%", color: "#5C6B54", fontFamily: "'Inter', sans-serif", fontSize: 12.5, cursor: "pointer" }}
            >
              + Add beer
            </button>
          </div>
        )}

        <button
          onClick={submit}
          disabled={!canSubmit}
          style={{ background: canSubmit ? "#5C9A3C" : "#E8E4D4", border: "none", borderRadius: 5, padding: "12px", color: canSubmit ? "#16191A" : "#A3AC94", fontFamily: "'Oswald', sans-serif", fontWeight: 500, fontSize: 15, letterSpacing: "0.03em", cursor: canSubmit ? "pointer" : "default" }}
        >
          Assemble {quantity || 0} pack{Number(quantity) !== 1 ? "s" : ""}
        </button>
      </div>
    </Modal>
  );
}

// A large floating panel for long review lists (TSW import, clear stock).
// It stops short of the top and bottom of the screen so the buttons are
// never hidden behind the iPad's edge or home bar, and it's rendered
// straight onto the page so no surrounding layout can clip it.
const SHEET_BACKDROP_STYLE = { position: "fixed", inset: 0, zIndex: 59, background: "rgba(10,12,11,0.6)" };
const SHEET_PANEL_STYLE = {
  position: "fixed",
  zIndex: 60,
  top: "calc(28px + env(safe-area-inset-top))",
  bottom: "calc(28px + env(safe-area-inset-bottom))",
  left: "50%",
  transform: "translateX(-50%)",
  width: "min(680px, calc(100vw - 32px))",
  background: "#F8F5EA",
  border: "1px solid #DDE0C8",
  borderRadius: 12,
  boxShadow: "0 12px 40px rgba(0,0,0,0.25)",
  display: "flex",
  flexDirection: "column",
  overflow: "hidden",
};

// Every clear-out ever made, newest first — rebuilt from the entries on each
// batch so one clear-out spread over many batches shows (and undoes) as one.
function stockClearHistory(batches) {
  const byId = {};
  batches.forEach((b) => {
    (b.stockCleared || []).forEach((e) => {
      if (!byId[e.id]) byId[e.id] = { id: e.id, date: e.date, user: e.user, reason: e.reason, kind: e.kind, counts: {}, batches: 0 };
      const h = byId[e.id];
      h.batches += 1;
      Object.entries(e.counts || {}).forEach(([k, v]) => (h.counts[k] = (h.counts[k] || 0) + v));
    });
  });
  return Object.values(byId).sort((a, b) => String(b.date).localeCompare(String(a.date)));
}

const containerCountsLabel = (counts) =>
  CONTAINERS.filter((c) => counts[c.key])
    .map((c) => (counts[c.key] < 0 ? `${-counts[c.key]} × ${c.shortLabel} put back` : `${counts[c.key]} × ${c.shortLabel}`))
    .join(", ");

const lastPackagedDate = (b) => packagingEvents(b).reduce((m, e) => (e.date && e.date > m ? e.date : m), "");

// Clears packaged stock in bulk — for starting stock control fresh (say in
// Xero) without deleting or changing the packaging behind it, which the
// excise records depend on. Pick what to keep: everything packaged from a
// date, and/or a number of units per product. Kept units come from the
// newest batches, so what's left is the freshest beer.
function ClearStockModal({ availableStock, batches, onClose, onConfirm }) {
  const [keepFrom, setKeepFrom] = useState("");
  const [keep, setKeep] = useState({});
  const [reason, setReason] = useState("Cleared before connecting Xero stock — already sold or accounted for");
  const [saving, setSaving] = useState(false);
  const batchById = useMemo(() => Object.fromEntries(batches.map((b) => [b.id, b])), [batches]);

  const products = useMemo(() => {
    const map = {};
    availableStock
      .filter((s) => s.available > 0)
      .forEach((s) => {
        const key = `${s.batchName}::${s.containerKey}`;
        if (!map[key]) map[key] = { key, name: s.batchName, containerKey: s.containerKey, containerLabel: s.containerLabel, rows: [], available: 0 };
        map[key].rows.push({ ...s, packedOn: lastPackagedDate(batchById[s.batchId] || {}) });
        map[key].available += s.available;
      });
    return Object.values(map).sort((a, b) => a.name.localeCompare(b.name) || a.containerKey.localeCompare(b.containerKey));
  }, [availableStock, batchById]);

  const plan = useMemo(() => {
    const perBatch = {};
    let cleared = 0;
    let kept = 0;
    let clearedL = 0;
    products.forEach((p) => {
      const newestFirst = [...p.rows].sort((a, b) => b.packedOn.localeCompare(a.packedOn));
      const byDate = keepFrom ? newestFirst.filter((r) => r.packedOn >= keepFrom).reduce((s2, r) => s2 + r.available, 0) : 0;
      const typed = Math.max(0, Math.floor(Number(keep[p.key]) || 0));
      let toKeep = Math.min(p.available, Math.max(typed, byDate));
      kept += toKeep;
      newestFirst.forEach((r) => {
        const k = Math.min(r.available, toKeep);
        toKeep -= k;
        const clear = r.available - k;
        if (clear > 0) {
          if (!perBatch[r.batchId]) perBatch[r.batchId] = {};
          perBatch[r.batchId][p.containerKey] = (perBatch[r.batchId][p.containerKey] || 0) + clear;
          cleared += clear;
          clearedL += clear * (CONTAINERS.find((c) => c.key === p.containerKey)?.volumeL || 0);
        }
      });
    });
    return { perBatch, cleared, kept, clearedL: Math.round(clearedL) };
  }, [products, keep, keepFrom]);

  const keptFor = (p) => {
    const byDate = keepFrom ? p.rows.filter((r) => r.packedOn >= keepFrom).reduce((s2, r) => s2 + r.available, 0) : 0;
    return Math.min(p.available, Math.max(Math.floor(Number(keep[p.key]) || 0), byDate));
  };

  const confirm = async () => {
    setSaving(true);
    const ok = await onConfirm(plan.perBatch, reason.trim());
    setSaving(false);
    if (ok) onClose();
  };

  return createPortal(
    <>
    <div style={SHEET_BACKDROP_STYLE} />
    <div style={SHEET_PANEL_STYLE}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 18px", borderBottom: "1px solid #DDE0C8", flexShrink: 0 }}>
        <h2 style={{ fontFamily: "'Oswald', sans-serif", fontSize: 20, color: "#2A3324", margin: 0, fontWeight: 500 }}>Clear packaged stock</h2>
        <button onClick={onClose} aria-label="Close" style={{ background: "none", border: "none", color: "#5C6B54", cursor: "pointer", padding: 10 }}>
          <X size={20} />
        </button>
      </div>
      <div style={{ flex: 1, overflowY: "auto", WebkitOverflowScrolling: "touch" }}>
        <div style={{ maxWidth: 640, margin: "0 auto", padding: "16px 18px 24px", display: "flex", flexDirection: "column", gap: 14 }}>
          <div style={{ fontSize: 12.5, color: "#5C6B54", lineHeight: 1.55 }}>
            Writes stock off so what's on hand starts fresh. Your batches and packaging records — and so your excise figures — don't change, and you can undo a clear-out afterwards. Anything you keep comes from the newest batches.
          </div>
          <label style={{ display: "flex", flexDirection: "column", gap: 5 }}>
            <span style={{ fontSize: 11, letterSpacing: "0.06em", textTransform: "uppercase", color: "#5C6B54" }}>Keep everything packaged on or after (optional)</span>
            <input type="date" value={keepFrom} onChange={(e) => setKeepFrom(e.target.value)} style={{ background: "#F5F1E4", border: "1px solid #DDE0C8", borderRadius: 4, padding: "9px 10px", fontSize: 14, color: "#2A3324" }} />
          </label>
          <div style={{ fontSize: 12, color: "#9BA88A" }}>Or type how many to keep for each product below. Leave at 0 to clear it all.</div>
          {products.length === 0 && <div style={{ color: "#9BA88A", fontSize: 13 }}>There's no packaged stock to clear.</div>}
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {products.map((p) => (
              <div key={p.key} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 12px", background: "#FFFFFF", border: "1px solid #DDE0C8", borderRadius: 6 }}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 13.5, color: "#2A3324" }}>{p.name}</div>
                  <div style={{ fontSize: 11.5, color: "#9BA88A" }}>
                    {p.containerLabel} · {p.available} on hand · clears {p.available - keptFor(p)}
                  </div>
                </div>
                <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, color: "#5C6B54" }}>
                  Keep
                  <input
                    type="number"
                    inputMode="numeric"
                    min="0"
                    max={p.available}
                    value={keep[p.key] ?? ""}
                    placeholder={String(keptFor(p))}
                    onChange={(e) => setKeep((prev) => ({ ...prev, [p.key]: e.target.value }))}
                    style={{ width: 70, background: "#F5F1E4", border: "1px solid #DDE0C8", borderRadius: 4, padding: "7px 8px", fontSize: 14, color: "#2A3324", fontFamily: "'JetBrains Mono', monospace" }}
                  />
                </label>
              </div>
            ))}
          </div>
          <label style={{ display: "flex", flexDirection: "column", gap: 5 }}>
            <span style={{ fontSize: 11, letterSpacing: "0.06em", textTransform: "uppercase", color: "#5C6B54" }}>Reason (kept on record)</span>
            <input value={reason} onChange={(e) => setReason(e.target.value)} style={{ background: "#F5F1E4", border: "1px solid #DDE0C8", borderRadius: 4, padding: "9px 10px", fontSize: 14, color: "#2A3324" }} />
          </label>
        </div>
      </div>
      <div style={{ flexShrink: 0, borderTop: "1px solid #DDE0C8", background: "#F8F5EA", padding: "12px 18px", display: "flex", justifyContent: "center" }}>
        <div style={{ width: "100%", maxWidth: 640, display: "flex", flexDirection: "column", gap: 8 }}>
          <div style={{ fontSize: 12.5, color: "#5C6B54", textAlign: "center" }}>
            Clearing {plan.cleared.toLocaleString("en-NZ")} units (about {plan.clearedL.toLocaleString("en-NZ")} L) · keeping {plan.kept.toLocaleString("en-NZ")}
          </div>
          <div style={{ display: "flex", gap: 10 }}>
            <button onClick={confirm} disabled={saving || plan.cleared === 0 || !reason.trim()} style={{ ...auditPrimaryBtn(!saving && plan.cleared > 0 && !!reason.trim()), flex: 2 }}>
              {saving ? "Clearing…" : "Clear stock"}
            </button>
            <button onClick={onClose} style={{ ...auditSecondaryBtn, flex: 1 }}>Cancel</button>
          </div>
        </div>
      </div>
    </div>
    </>,
    document.body
  );
}

// Matches every Xero item to the Brewpoint beer and container it is, so a
// sale invoiced in Xero takes the right stock off. Several Xero items can
// be the same beer (Craftys / Gents / Moon Juice labels), and "units"
// handles cases: a case-of-24 item takes 24 cans off per case sold.
function XeroItemMatchModal({ xeroItems, beerNames, existing, highlightCodes, onClose, onSave }) {
  const byCode = useMemo(() => Object.fromEntries((existing || []).map((m) => [String(m.xero_item_code).toLowerCase(), m])), [existing]);
  const [rows, setRows] = useState(() =>
    (xeroItems || []).map((it) => {
      const m = byCode[String(it.code).toLowerCase()];
      if (m) {
        return { code: it.code, name: it.name, beerName: m.ignore ? "__ignore" : m.beer_name || "", containerKey: m.container_key || "", units: String(m.units_per_xero_unit ?? 1), saved: true };
      }
      const g = guessXeroItemMatch(it, beerNames);
      return { code: it.code, name: it.name, beerName: g.beerName, containerKey: g.containerKey, units: String(g.units), saved: false };
    })
  );
  const [filter, setFilter] = useState("todo");
  const [saving, setSaving] = useState(false);
  const highlight = new Set((highlightCodes || []).map((c) => String(c).toLowerCase()));
  const update = (code, patch) => setRows((prev) => prev.map((r) => (r.code === code ? { ...r, ...patch } : r)));
  const complete = (r) => r.beerName === "__ignore" || (r.beerName && r.containerKey && Number(r.units) > 0);
  const shown = rows
    .filter((r) => (filter === "todo" ? !r.saved || highlight.has(String(r.code).toLowerCase()) : true))
    .sort((a, b) => (highlight.has(String(b.code).toLowerCase()) - highlight.has(String(a.code).toLowerCase())) || a.code.localeCompare(b.code));
  const toSave = rows.filter((r) => complete(r));
  const selectStyle = { background: "#F5F1E4", border: "1px solid #DDE0C8", borderRadius: 4, padding: "7px 8px", fontSize: 13, color: "#2A3324", minWidth: 0 };

  const save = async () => {
    setSaving(true);
    const ok = await onSave(
      toSave.map((r) => ({
        xero_item_code: r.code,
        xero_item_name: r.name,
        ignore: r.beerName === "__ignore",
        beer_name: r.beerName === "__ignore" ? null : r.beerName,
        container_key: r.beerName === "__ignore" ? null : r.containerKey,
        product_key: r.beerName === "__ignore" ? null : productKeyFor(r.beerName, r.containerKey),
        units_per_xero_unit: r.beerName === "__ignore" ? 1 : Number(r.units) || 1,
      }))
    );
    setSaving(false);
    if (ok) onClose();
  };

  return createPortal(
    <>
      <div style={SHEET_BACKDROP_STYLE} />
      <div style={SHEET_PANEL_STYLE}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 18px", borderBottom: "1px solid #DDE0C8", flexShrink: 0 }}>
          <h2 style={{ fontFamily: "'Oswald', sans-serif", fontSize: 20, color: "#2A3324", margin: 0, fontWeight: 500 }}>Match Xero items to beers</h2>
          <button onClick={onClose} aria-label="Close" style={{ background: "none", border: "none", color: "#5C6B54", cursor: "pointer", padding: 10 }}>
            <X size={20} />
          </button>
        </div>
        <div style={{ flex: 1, overflowY: "auto", WebkitOverflowScrolling: "touch" }}>
          <div style={{ padding: "14px 18px 20px", display: "flex", flexDirection: "column", gap: 10 }}>
            <div style={{ fontSize: 12.5, color: "#5C6B54", lineHeight: 1.5 }}>
              Pick the beer and container each Xero item is. <strong>Units</strong> is how many Brewpoint units one Xero unit holds — 24 for a case of 24 cans, 1 for a keg. Items that aren't beer (hops, consulting, equipment) can be set to "Not stock". Best guesses are filled in — check them.
            </div>
            <div style={{ display: "flex", border: "1px solid #DDE0C8", borderRadius: 4, overflow: "hidden" }}>
              {[["todo", `To check (${rows.filter((r) => !r.saved || highlight.has(String(r.code).toLowerCase())).length})`], ["all", `All items (${rows.length})`]].map(([k, l]) => (
                <button key={k} onClick={() => setFilter(k)} style={{ flex: 1, background: filter === k ? "#5C9A3C" : "#F5F1E4", border: "none", padding: 9, color: filter === k ? "#16191A" : "#5C6B54", fontSize: 12.5, cursor: "pointer" }}>{l}</button>
              ))}
            </div>
            {shown.length === 0 && <div style={{ color: "#9BA88A", fontSize: 13, padding: "8px 0" }}>Everything's matched.</div>}
            {shown.map((r) => (
              <div key={r.code} style={{ background: "#FFFFFF", border: `1px solid ${highlight.has(String(r.code).toLowerCase()) ? "#D9A441" : "#DDE0C8"}`, borderRadius: 6, padding: "9px 12px", display: "flex", flexDirection: "column", gap: 7 }}>
                <div style={{ fontSize: 13, color: "#2A3324" }}>
                  <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12, color: "#5C6B54" }}>{r.code}</span> · {r.name}
                  {highlight.has(String(r.code).toLowerCase()) && <span style={{ color: "#8A6D0B", fontSize: 11.5 }}> — sold recently, not matched yet</span>}
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "2fr 1.3fr 0.7fr", gap: 6 }}>
                  <select value={r.beerName} onChange={(e) => update(r.code, { beerName: e.target.value })} style={selectStyle}>
                    <option value="">Choose beer…</option>
                    <option value="__ignore">Not stock — ignore</option>
                    {beerNames.map((n) => <option key={n} value={n}>{n}</option>)}
                  </select>
                  <select value={r.containerKey} disabled={r.beerName === "__ignore"} onChange={(e) => update(r.code, { containerKey: e.target.value, units: e.target.value === "cans330" ? (r.units === "1" ? "24" : r.units) : "1" })} style={selectStyle}>
                    <option value="">Container…</option>
                    {CONTAINERS.map((c) => <option key={c.key} value={c.key}>{c.label}</option>)}
                  </select>
                  <input type="number" inputMode="numeric" min="1" disabled={r.beerName === "__ignore"} value={r.units} onChange={(e) => update(r.code, { units: e.target.value })} aria-label="Units per Xero unit" style={{ ...selectStyle, width: "100%", boxSizing: "border-box", fontFamily: "'JetBrains Mono', monospace" }} />
                </div>
              </div>
            ))}
          </div>
        </div>
        <div style={{ flexShrink: 0, borderTop: "1px solid #DDE0C8", padding: "12px 18px", display: "flex", gap: 10 }}>
          <button onClick={save} disabled={saving || toSave.length === 0} style={{ ...auditPrimaryBtn(!saving && toSave.length > 0), flex: 2 }}>
            {saving ? "Saving…" : `Save ${toSave.length} match${toSave.length === 1 ? "" : "es"}`}
          </button>
          <button onClick={onClose} style={{ ...auditSecondaryBtn, flex: 1 }}>Cancel</button>
        </div>
      </div>
    </>,
    document.body
  );
}

// ─── Compare Brewpoint's stock with Xero's, and line Brewpoint up ───────────
// Xero items are turned into Brewpoint products through the same matches
// the sales sync uses (several Xero items can be one beer; a case of 24 is
// 24 cans). Brewpoint's side is what's on hand per beer + container.
function compareXeroStock({ xeroItems, salesMap, itemMappings, availableStock }) {
  const mapByCode = {};
  (salesMap || []).forEach((m) => (mapByCode[String(m.xero_item_code).toLowerCase()] = m));
  const resolve = (code) => {
    const m = mapByCode[String(code).toLowerCase()];
    if (m) return m.ignore ? { ignore: true } : m.product_key ? { productKey: m.product_key, beerName: m.beer_name, containerKey: m.container_key || m.product_key.split("::")[1], units: Number(m.units_per_xero_unit) || 1 } : null;
    const fm = (itemMappings || []).find((x) => String(x.xero_item_code).toLowerCase() === String(code).toLowerCase());
    if (fm) return { productKey: fm.product_key, beerName: (fm.product_label || "").split(" — ")[0] || fm.product_key.split("::")[0], containerKey: fm.product_key.split("::")[1], units: 1 };
    return null;
  };

  const products = {};
  const productFor = (key, name, containerKey) =>
    products[key] || (products[key] = { key, name, containerKey, xero: 0, xeroItems: [], brewpoint: 0, inXero: false, inBrewpoint: false });
  (availableStock || []).forEach((s) => {
    const p = productFor(productKeyFor(s.batchName, s.containerKey), s.batchName.trim(), s.containerKey);
    p.brewpoint += s.available;
    p.inBrewpoint = true;
  });
  const unmatched = [];
  (xeroItems || []).forEach((it) => {
    if (!it.tracked) return;
    const r = resolve(it.code);
    if (r && r.ignore) return;
    if (!r) {
      if (Number(it.qtyOnHand) !== 0) unmatched.push(it);
      return;
    }
    const p = productFor(r.productKey, products[r.productKey]?.name || r.beerName || r.productKey.split("::")[0], r.containerKey);
    p.xero += Math.round((Number(it.qtyOnHand) || 0) * r.units * 1000) / 1000;
    p.xeroItems.push(`${it.code} × ${Number(it.qtyOnHand) || 0}${r.units !== 1 ? ` (${r.units} each)` : ""}`);
    p.inXero = true;
  });
  const rows = Object.values(products)
    .filter((p) => p.inXero || p.brewpoint !== 0)
    .map((p) => ({ ...p, brewpoint: Math.round(p.brewpoint * 1000) / 1000, diff: Math.round((p.xero - p.brewpoint) * 1000) / 1000 }))
    .sort((a, b) => (b.diff !== 0) - (a.diff !== 0) || a.name.localeCompare(b.name) || a.containerKey.localeCompare(b.containerKey));
  return { rows, unmatched };
}

// Turns the chosen differences into per-batch stock entries. Too much in
// Brewpoint → written off from the oldest batches first (the freshest beer
// stays). Too little → put back on the newest batches first, undoing
// earlier clear-outs/write-offs before anything else; anything beyond that
// goes on the newest batch.
function planXeroStockMatch({ rows, availableStock, batches }) {
  const batchById = Object.fromEntries((batches || []).map((b) => [b.id, b]));
  const offPerBatch = {};
  const backPerBatch = {};
  const add = (target, batchId, containerKey, qty) => {
    if (!target[batchId]) target[batchId] = {};
    target[batchId][containerKey] = Math.round(((target[batchId][containerKey] || 0) + qty) * 1000) / 1000;
  };
  rows.forEach((row) => {
    const lines = (availableStock || [])
      .filter((s) => productKeyFor(s.batchName, s.containerKey) === row.key)
      .map((s) => ({ ...s, packedOn: lastPackagedDate(batchById[s.batchId] || {}) }));
    if (row.diff < 0) {
      let need = -row.diff;
      [...lines].sort((a, b) => a.packedOn.localeCompare(b.packedOn)).forEach((s) => {
        const take = Math.min(need, Math.max(0, s.available));
        if (take <= 0) return;
        add(offPerBatch, s.batchId, s.containerKey, take);
        need -= take;
      });
    } else if (row.diff > 0) {
      let need = row.diff;
      const newest = [...lines].sort((a, b) => b.packedOn.localeCompare(a.packedOn));
      newest.forEach((s) => {
        if (need <= 0) return;
        const b = batchById[s.batchId];
        const writtenOff =
          (b?.stockCleared || []).reduce((t, e) => t + (Number(e.counts?.[s.containerKey]) || 0), 0) +
          (b?.xeroSold || []).filter((e) => e.containerKey === s.containerKey).reduce((t, e) => t + (Number(e.qty) || 0), 0);
        const give = Math.min(need, Math.max(0, writtenOff));
        if (give <= 0) return;
        add(backPerBatch, s.batchId, s.containerKey, give);
        need -= give;
      });
      if (need > 0 && newest[0]) add(backPerBatch, newest[0].batchId, newest[0].containerKey, need);
    }
  });
  return { offPerBatch, backPerBatch };
}

function XeroStockCompareModal({ xeroItems, salesMap, itemMappings, availableStock, onClose, onMatch, onMatchItems }) {
  const { rows, unmatched } = useMemo(() => compareXeroStock({ xeroItems, salesMap, itemMappings, availableStock }), [xeroItems, salesMap, itemMappings, availableStock]);
  const [picked, setPicked] = useState(() => Object.fromEntries(rows.filter((r) => r.diff !== 0 && r.inXero && r.inBrewpoint).map((r) => [r.key, true])));
  const [saving, setSaving] = useState(false);
  const chosen = rows.filter((r) => picked[r.key] && r.diff !== 0 && r.inXero && r.inBrewpoint);
  const containerShort = (k) => CONTAINERS.find((c) => c.key === k)?.label || k;
  const num = (n) => (Math.round(n * 1000) / 1000).toLocaleString("en-NZ");
  const cell = { fontFamily: "'JetBrains Mono', monospace", fontSize: 13, textAlign: "right", whiteSpace: "nowrap" };

  const confirm = async () => {
    setSaving(true);
    const ok = await onMatch(chosen);
    setSaving(false);
    if (ok) onClose();
  };

  return createPortal(
    <>
      <div style={SHEET_BACKDROP_STYLE} />
      <div style={SHEET_PANEL_STYLE}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 18px", borderBottom: "1px solid #DDE0C8", flexShrink: 0 }}>
          <h2 style={{ fontFamily: "'Oswald', sans-serif", fontSize: 20, color: "#2A3324", margin: 0, fontWeight: 500 }}>Compare with Xero</h2>
          <button onClick={onClose} aria-label="Close" style={{ background: "none", border: "none", color: "#5C6B54", cursor: "pointer", padding: 10 }}>
            <X size={20} />
          </button>
        </div>
        <div style={{ flex: 1, overflowY: "auto", WebkitOverflowScrolling: "touch" }}>
          <div style={{ padding: "14px 18px 20px", display: "flex", flexDirection: "column", gap: 10 }}>
            <div style={{ fontSize: 12.5, color: "#5C6B54", lineHeight: 1.5 }}>
              Xero's stock on hand next to Brewpoint's, in Brewpoint units (cans and kegs). Tick the lines to bring Brewpoint into line with Xero.
              Extra stock is written off from the oldest batch; missing stock goes back on the newest. Your packaging and excise records don't change, and you can undo it from Finished stock.
            </div>
            {unmatched.length > 0 && (
              <div style={{ background: "#FBF3DC", border: "1px solid #E3D3A0", borderRadius: 5, padding: "8px 10px", color: "#8A6D0B", fontSize: 12, lineHeight: 1.45 }}>
                Xero has stock of {unmatched.length} item{unmatched.length === 1 ? "" : "s"} not matched to a beer yet: {unmatched.map((i) => `${i.code} (${i.qtyOnHand})`).join(", ")}.{" "}
                <button onClick={onMatchItems} style={{ background: "none", border: "none", padding: 0, color: "#5C9A3C", textDecoration: "underline", fontSize: 12, cursor: "pointer" }}>Match Xero items</button>
              </div>
            )}
            {rows.length === 0 && <div style={{ color: "#9BA88A", fontSize: 13 }}>No stock in either Xero or Brewpoint to compare.</div>}
            {rows.length > 0 && (
              <div style={{ background: "#FFFFFF", border: "1px solid #DDE0C8", borderRadius: 6, overflow: "hidden" }}>
                <div style={{ display: "grid", gridTemplateColumns: "28px 1fr 64px 76px 64px", gap: 6, padding: "8px 10px", background: "#F5F1E4", fontSize: 10.5, letterSpacing: "0.05em", textTransform: "uppercase", color: "#5C6B54" }}>
                  <span />
                  <span>Product</span>
                  <span style={{ textAlign: "right" }}>Xero</span>
                  <span style={{ textAlign: "right" }}>Brewpoint</span>
                  <span style={{ textAlign: "right" }}>Change</span>
                </div>
                {rows.map((r) => {
                  const canPick = r.diff !== 0 && r.inXero && r.inBrewpoint;
                  return (
                    <label key={r.key} style={{ display: "grid", gridTemplateColumns: "28px 1fr 64px 76px 64px", gap: 6, alignItems: "center", padding: "9px 10px", borderTop: "1px solid #EEF0E2", cursor: canPick ? "pointer" : "default" }}>
                      <input type="checkbox" disabled={!canPick} checked={!!picked[r.key] && canPick} onChange={(e) => setPicked((prev) => ({ ...prev, [r.key]: e.target.checked }))} />
                      <span style={{ minWidth: 0 }}>
                        <span style={{ fontSize: 13, color: "#2A3324" }}>{r.name}</span>
                        <span style={{ display: "block", fontSize: 11, color: "#9BA88A" }}>
                          {containerShort(r.containerKey)}
                          {r.inXero ? ` · ${r.xeroItems.join(", ")}` : " · not matched to a Xero item"}
                          {r.inXero && !r.inBrewpoint ? " · never packaged in Brewpoint" : ""}
                        </span>
                      </span>
                      <span style={{ ...cell, color: r.inXero ? "#2A3324" : "#C3C9B0" }}>{r.inXero ? num(r.xero) : "—"}</span>
                      <span style={{ ...cell, color: "#2A3324" }}>{num(r.brewpoint)}</span>
                      <span style={{ ...cell, color: r.diff === 0 ? "#9BA88A" : r.diff > 0 ? "#5C9A3C" : "#B5502F" }}>{r.diff === 0 || !r.inXero ? "✓" : `${r.diff > 0 ? "+" : "−"}${num(Math.abs(r.diff))}`}</span>
                    </label>
                  );
                })}
              </div>
            )}
          </div>
        </div>
        <div style={{ flexShrink: 0, borderTop: "1px solid #DDE0C8", padding: "12px 18px", display: "flex", gap: 10 }}>
          <button onClick={confirm} disabled={saving || chosen.length === 0} style={{ ...auditPrimaryBtn(!saving && chosen.length > 0), flex: 2 }}>
            {saving ? "Updating…" : chosen.length === 0 ? "Everything matches" : `Match Brewpoint to Xero (${chosen.length})`}
          </button>
          <button onClick={onClose} style={{ ...auditSecondaryBtn, flex: 1 }}>Close</button>
        </div>
      </div>
    </>,
    document.body
  );
}

function FinishedGoodsStockView({
  availableStock,
  onStartStockTake,
  onOpenHistory,
  stockTakeCount,
  mixedPackTypes,
  mixedPackStock,
  onNewMixedPackType,
  onEditMixedPackType,
  onAssembleMixedPack,
  batches = [],
  onClearStock,
  onUndoClear,
  onCompareXero,
}) {
  const [showSoldOut, setShowSoldOut] = useState(false);
  // On hand means available right now — sold-out and cleared lines stay
  // hidden unless asked for.
  const everPackaged = availableStock.filter((s) => s.packaged > 0);
  const relevant = showSoldOut ? everPackaged : everPackaged.filter((s) => s.available > 0);
  const soldOutCount = everPackaged.filter((s) => s.available <= 0).length;
  const clearHistory = stockClearHistory(batches);
  const grouped = {};
  relevant.forEach((s) => {
    if (!grouped[s.batchName]) grouped[s.batchName] = [];
    grouped[s.batchName].push(s);
  });
  const beerNames = Object.keys(grouped).sort();

  return (
    <div>
      <div style={{ display: "flex", gap: 8, marginBottom: 18 }}>
        <button
          data-tour="page-finishedGoodsStock-stocktake"
          onClick={onStartStockTake}
          style={{ flex: 1, background: "#EBE8D6", border: "1px solid #C9D1AC", borderRadius: 5, padding: "9px", color: "#2A3324", fontFamily: "'Inter', sans-serif", fontSize: 12.5, cursor: "pointer" }}
        >
          Start stock take
        </button>
        <button
          onClick={onOpenHistory}
          style={{ flex: 1, background: "none", border: "1px solid #DDE0C8", borderRadius: 5, padding: "9px", color: "#5C6B54", fontFamily: "'Inter', sans-serif", fontSize: 12.5, cursor: "pointer" }}
        >
          Past reports ({stockTakeCount})
        </button>
        {onClearStock && (
          <button
            onClick={onClearStock}
            style={{ flex: 1, background: "none", border: "1px solid #DDE0C8", borderRadius: 5, padding: "9px", color: "#B5502F", fontFamily: "'Inter', sans-serif", fontSize: 12.5, cursor: "pointer" }}
          >
            Clear stock…
          </button>
        )}
      </div>
      {onCompareXero && (
        <button
          onClick={onCompareXero}
          style={{ width: "100%", marginTop: -8, marginBottom: 18, background: "#EBE8D6", border: "1px solid #C9D1AC", borderRadius: 5, padding: "9px", color: "#2A3324", fontFamily: "'Inter', sans-serif", fontSize: 12.5, cursor: "pointer" }}
        >
          Compare with Xero
        </button>
      )}

      {clearHistory.length > 0 && (
        <div style={{ marginBottom: 20, display: "flex", flexDirection: "column", gap: 6 }}>
          {clearHistory.map((h) => (
            <div key={h.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, padding: "9px 12px", background: "#FBF7EA", border: "1px solid #E8DFC0", borderRadius: 6 }}>
              <div style={{ fontSize: 12, color: "#5C6B54", lineHeight: 1.45 }}>
                <strong style={{ color: "#2A3324" }}>{h.kind === "xero-match" ? "Matched to Xero" : "Cleared"} {String(h.date).slice(0, 10)}</strong> by {h.user || "someone"} — {containerCountsLabel(h.counts)}
                {h.reason ? <div style={{ color: "#9BA88A" }}>{h.reason}</div> : null}
              </div>
              {onUndoClear && (
                <button
                  onClick={() => {
                    if (window.confirm(h.kind === "xero-match" ? "Undo this Xero match? Stock goes back to what it was before." : "Undo this clear-out? That stock will show as on hand again.")) onUndoClear(h.id);
                  }}
                  style={{ background: "none", border: "1px solid #DDE0C8", borderRadius: 5, padding: "6px 10px", color: "#5C6B54", fontSize: 12, cursor: "pointer", whiteSpace: "nowrap" }}
                >
                  Undo
                </button>
              )}
            </div>
          ))}
        </div>
      )}

      <div style={{ marginBottom: 24 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <div style={{ fontFamily: "'Oswald', sans-serif", fontWeight: 500, fontSize: 14.5, color: "#2A3324" }}>Mixed packs</div>
          <button
            onClick={onNewMixedPackType}
            style={{ background: "none", border: "none", color: "#5C9A3C", cursor: "pointer", fontSize: 12, fontFamily: "'Inter', sans-serif", padding: 0 }}
          >
            + New mixed pack
          </button>
        </div>
        {mixedPackTypes.length === 0 ? (
          <div style={{ color: "#9BA88A", fontSize: 13 }}>
            Combine beers already in stock into a variety pack — fixed recipe or built fresh each time.
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            {mixedPackStock.map((t) => (
              <div key={t.id} style={{ padding: "10px 14px", background: "#FFFFFF", border: "1px solid #DDE0C8", borderRadius: 6 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <button onClick={() => onEditMixedPackType(t)} style={{ background: "none", border: "none", padding: 0, textAlign: "left", cursor: "pointer" }}>
                    <div style={{ color: "#2A3324", fontSize: 13.5, fontFamily: "'Inter', sans-serif" }}>{t.name}</div>
                    <div style={{ color: "#9BA88A", fontSize: 11 }}>
                      {t.mode === "fixed" ? "Fixed recipe" : "Built fresh each time"} · {t.totalUnits} units
                      {t.price != null ? ` · $${t.price.toFixed(2)}` : ""}
                    </div>
                  </button>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 13, color: t.available <= 0 ? "#B5502F" : "#5C9A3C" }}>
                      {t.available} available
                    </span>
                    <button
                      onClick={() => onAssembleMixedPack(t)}
                      style={{ background: "#EBE8D6", border: "1px solid #C9D1AC", borderRadius: 5, padding: "7px 12px", color: "#2A3324", fontFamily: "'Inter', sans-serif", fontSize: 12, cursor: "pointer" }}
                    >
                      Assemble
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <div style={{ fontFamily: "'Oswald', sans-serif", fontWeight: 500, fontSize: 14.5, color: "#2A3324" }}>{showSoldOut ? "All packaged stock" : "In stock now"}</div>
        {soldOutCount > 0 && (
          <button onClick={() => setShowSoldOut((v) => !v)} style={{ background: "none", border: "none", color: "#5C9A3C", cursor: "pointer", fontSize: 12, fontFamily: "'Inter', sans-serif", padding: 0 }}>
            {showSoldOut ? "Hide sold out" : `Show sold out (${soldOutCount})`}
          </button>
        )}
      </div>
      {beerNames.length === 0 ? (
        everPackaged.length > 0 ? (
          <EmptyState icon={Package} title="Nothing in stock" subtitle="Everything packaged has been sold or cleared. New packaging runs show up here automatically." />
        ) : (
          <EmptyState icon={Package} title="Nothing packaged yet" subtitle="Once a batch is packaged, what's available to sell will show up here automatically." />
        )
      ) : (
        beerNames.map((name) => (
          <div key={name} style={{ marginBottom: 20 }}>
            <div style={{ fontFamily: "'Oswald', sans-serif", fontWeight: 500, fontSize: 14.5, color: "#2A3324", marginBottom: 8 }}>{name}</div>
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              {grouped[name].map((s) => (
                <div
                  key={s.containerKey}
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    padding: "10px 14px",
                    background: "#FFFFFF",
                    border: `1px solid ${s.available <= 0 ? "#E3D3A0" : "#DDE0C8"}`,
                    borderRadius: 6,
                  }}
                >
                  <span style={{ color: "#2A3324", fontSize: 13.5 }}>{s.containerLabel}</span>
                  <span
                    style={{
                      fontFamily: "'JetBrains Mono', monospace",
                      fontSize: 13,
                      color: s.available <= 0 ? "#B5502F" : "#5C9A3C",
                    }}
                  >
                    {s.available} available
                  </span>
                </div>
              ))}
            </div>
          </div>
        ))
      )}
    </div>
  );
}

function CustomersView({ customers, onOpen, onImportXero }) {
  const [query, setQuery] = useState("");
  const q = query.trim().toLowerCase();
  const filtered = q
    ? customers.filter((c) => c.name.toLowerCase().includes(q) || (c.contactName || "").toLowerCase().includes(q))
    : customers;

  return (
    <div>
      {onImportXero && (
        <button
          onClick={onImportXero}
          style={{ background: "none", border: "none", color: "#5C9A3C", cursor: "pointer", fontSize: 12, fontFamily: "'Inter', sans-serif", padding: 0, marginBottom: 10, display: "block" }}
        >
          Import customers from Xero
        </button>
      )}
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search customers by name or contact…"
        style={{
          width: "100%",
          boxSizing: "border-box",
          background: "#F5F1E4",
          border: "1px solid #DDE0C8",
          borderRadius: 5,
          padding: "10px 12px",
          color: "#2A3324",
          fontFamily: "'Inter', sans-serif",
          fontSize: 14,
          marginBottom: 16,
        }}
      />
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        {filtered.map((c) => (
          <CustomerCard key={c.id} customer={c} onOpen={onOpen} />
        ))}
      </div>
      {customers.length === 0 && (
        <EmptyState
          icon={Users}
          title="No customers yet"
          subtitle="Add the businesses you sell to — wholesale accounts, bars, bottle shops — so you can start tracking orders against them."
        />
      )}
      {customers.length > 0 && filtered.length === 0 && (
        <div style={{ color: "#9BA88A", fontSize: 13, textAlign: "center", padding: "24px 0" }}>No customers match "{query}".</div>
      )}
    </div>
  );
}

// Picks (or creates) the Xero contact this customer maps to. Kept
// deliberately simple — search the list Xero already has, or push this
// customer's details into Xero as a brand-new contact.
// Bulk-imports selected Xero contacts as new customers, already linked —
// for a brewery switching from Xero-only bookkeeping, so their existing
// customer list doesn't need retyping from scratch.
// Proactively maps recipes (by name, per container type) to Xero items —
// pre-fills the same xero_item_mappings table the app already checks the
// moment a batch is packaged, so a brewery bringing an existing product
// list from Xero doesn't have to wait for the first real batch of each
// beer to be prompted individually. Only carries through automatically
// to a future batch whose name matches the recipe's exactly — a batch
// named with a size or brew-day suffix still gets prompted as normal.
function XeroProductMappingModal({ recipes, xeroItems, existingMappings, onClose, onSave }) {
  const [selections, setSelections] = useState(() => {
    const init = {};
    recipes.forEach((r) => {
      CONTAINERS.forEach((c) => {
        const key = productKeyFor(r.name, c.key);
        const existing = existingMappings.find((m) => m.product_key === key);
        init[`${r.id}:${c.key}`] = { itemCode: existing ? existing.xero_item_code : "", unitCost: existing ? String(existing.unit_cost) : "" };
      });
    });
    return init;
  });
  const [saving, setSaving] = useState(false);

  const setSelection = (recipeId, containerKey, patch) =>
    setSelections((prev) => ({ ...prev, [`${recipeId}:${containerKey}`]: { ...prev[`${recipeId}:${containerKey}`], ...patch } }));

  const submit = async () => {
    setSaving(true);
    const lines = [];
    recipes.forEach((r) => {
      CONTAINERS.forEach((c) => {
        const sel = selections[`${r.id}:${c.key}`];
        if (!sel.itemCode) return;
        const item = xeroItems.find((i) => i.itemCode === sel.itemCode);
        if (!item) return;
        lines.push({
          productKey: productKeyFor(r.name, c.key),
          productLabel: `${r.name} — ${c.label}`,
          itemCode: item.itemCode,
          itemName: item.name,
          unitCost: sel.unitCost === "" ? 0 : Number(sel.unitCost),
        });
      });
    });
    await onSave(lines);
    setSaving(false);
    onClose();
  };

  const mappedCount = Object.values(selections).filter((s) => s.itemCode).length;

  return (
    <Modal title="Map recipes to Xero items" onClose={onClose}>
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        <div style={{ color: "#5C6B54", fontSize: 13 }}>
          For each recipe, match its packaged sizes to the matching item already set up in Xero, and give it a unit cost — this is what gets recorded as the stock value in Xero each time it's packaged. Only applies automatically to a future batch whose name matches the recipe exactly; a differently-named batch still gets asked at packaging time, same as always.
        </div>
        {xeroItems.length === 0 ? (
          <div style={{ color: "#9BA88A", fontSize: 13 }}>Loading Xero items…</div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 16, maxHeight: 420, overflowY: "auto" }}>
            {recipes.map((r) => (
              <div key={r.id} style={{ background: "#F8F5EA", border: "1px solid #EBE8D6", borderRadius: 6, padding: "12px 14px" }}>
                <div style={{ fontFamily: "'Oswald', sans-serif", fontWeight: 500, fontSize: 14, color: "#2A3324", marginBottom: 10 }}>{r.name}</div>
                <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                  {CONTAINERS.map((c) => {
                    const sel = selections[`${r.id}:${c.key}`];
                    return (
                      <div key={c.key} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                        <span style={{ width: 68, flexShrink: 0, color: "#5C6B54", fontSize: 12.5 }}>{c.shortLabel}</span>
                        <select
                          value={sel.itemCode}
                          onChange={(e) => setSelection(r.id, c.key, { itemCode: e.target.value })}
                          style={{ flex: 1, boxSizing: "border-box", background: "#FFFFFF", border: "1px solid #DDE0C8", borderRadius: 4, padding: "7px 8px", color: "#2A3324", fontFamily: "'Inter', sans-serif", fontSize: 13 }}
                        >
                          <option value="">Not mapped</option>
                          {xeroItems.map((item) => (
                            <option key={item.itemCode} value={item.itemCode}>
                              {item.name}
                            </option>
                          ))}
                        </select>
                        {sel.itemCode && (
                          <input
                            type="number"
                            step="0.01"
                            value={sel.unitCost}
                            onChange={(e) => setSelection(r.id, c.key, { unitCost: e.target.value })}
                            placeholder="Unit cost"
                            style={{ width: 84, flexShrink: 0, boxSizing: "border-box", background: "#FFFFFF", border: "1px solid #DDE0C8", borderRadius: 4, padding: "7px 8px", color: "#2A3324", fontFamily: "'Inter', sans-serif", fontSize: 13 }}
                          />
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
        )}
        <button
          onClick={submit}
          disabled={saving || xeroItems.length === 0}
          style={{
            background: saving || xeroItems.length === 0 ? "#E8E4D4" : "#5C9A3C",
            border: "none",
            borderRadius: 5,
            padding: "12px",
            color: saving || xeroItems.length === 0 ? "#A3AC94" : "#16191A",
            fontFamily: "'Oswald', sans-serif",
            fontWeight: 500,
            fontSize: 15,
            cursor: saving || xeroItems.length === 0 ? "default" : "pointer",
          }}
        >
          {saving ? "Saving…" : `Save ${mappedCount} mapping${mappedCount !== 1 ? "s" : ""}`}
        </button>
      </div>
    </Modal>
  );
}

function ImportXeroContactsModal({ contacts, existingCustomers, onClose, onImport }) {
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState(() => new Set());
  const [importing, setImporting] = useState(false);
  const q = query.trim().toLowerCase();

  const alreadyLinkedIds = new Set(existingCustomers.map((c) => c.xeroContactId).filter(Boolean));
  const importable = contacts.filter((c) => !alreadyLinkedIds.has(c.contactId));
  const filtered = q ? importable.filter((c) => c.name.toLowerCase().includes(q)) : importable;

  const toggle = (id) => setSelected((prev) => { const next = new Set(prev); next.has(id) ? next.delete(id) : next.add(id); return next; });
  const toggleAll = () => setSelected(selected.size === filtered.length ? new Set() : new Set(filtered.map((c) => c.contactId)));

  const submit = async () => {
    setImporting(true);
    await onImport(contacts.filter((c) => selected.has(c.contactId)));
    setImporting(false);
    onClose();
  };

  return (
    <Modal title="Import customers from Xero" onClose={onClose}>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <div style={{ color: "#5C6B54", fontSize: 13 }}>
          Tick the Xero contacts to bring in as customers — each one's created already linked to Xero, ready for invoicing.
          {existingCustomers.length > 0 && alreadyLinkedIds.size > 0 && ` ${alreadyLinkedIds.size} already linked contact${alreadyLinkedIds.size !== 1 ? "s" : ""} hidden below.`}
        </div>
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search Xero contacts…"
          style={{ width: "100%", boxSizing: "border-box", background: "#F5F1E4", border: "1px solid #DDE0C8", borderRadius: 5, padding: "9px 10px", color: "#2A3324", fontFamily: "'Inter', sans-serif", fontSize: 14 }}
        />
        {filtered.length > 0 && (
          <button onClick={toggleAll} style={{ alignSelf: "flex-start", background: "none", border: "none", color: "#5C9A3C", fontSize: 12.5, cursor: "pointer", padding: 0 }}>
            {selected.size === filtered.length ? "Deselect all" : `Select all (${filtered.length})`}
          </button>
        )}
        {contacts.length === 0 ? (
          <div style={{ color: "#9BA88A", fontSize: 13 }}>Loading Xero contacts…</div>
        ) : filtered.length === 0 ? (
          <div style={{ color: "#9BA88A", fontSize: 13 }}>{q ? `No contacts match "${query}".` : "Every Xero contact is already linked."}</div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 320, overflowY: "auto" }}>
            {filtered.map((c) => (
              <label
                key={c.contactId}
                style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", background: "#F8F5EA", border: "1px solid #EBE8D6", borderRadius: 5, fontSize: 13.5, color: "#2A3324", cursor: "pointer" }}
              >
                <input type="checkbox" checked={selected.has(c.contactId)} onChange={() => toggle(c.contactId)} style={{ flexShrink: 0, width: 17, height: 17 }} />
                {c.name}
              </label>
            ))}
          </div>
        )}
        <button
          onClick={submit}
          disabled={selected.size === 0 || importing}
          style={{
            background: selected.size === 0 || importing ? "#E8E4D4" : "#5C9A3C",
            border: "none",
            borderRadius: 5,
            padding: "12px",
            color: selected.size === 0 || importing ? "#A3AC94" : "#16191A",
            fontFamily: "'Oswald', sans-serif",
            fontWeight: 500,
            fontSize: 15,
            cursor: selected.size === 0 || importing ? "default" : "pointer",
          }}
        >
          {importing ? "Importing…" : `Import ${selected.size} customer${selected.size !== 1 ? "s" : ""}`}
        </button>
      </div>
    </Modal>
  );
}

